local config = {
  ui_story_5061_50610101_1_dialog_content = "Catatan Investigasi, Entri 154.",
  ui_story_5061_50610101_2_dialog_content = "27 September, 22:00. Bersalju.",
  ui_story_5061_50610101_3_dialog_content = "Setelah bepergian ke ujung terjauh Northland, saat ini saya sedang mendekati lokasi <color=#FFB400>Badai Aurora</color> yang berusia seabad.",
  ui_story_5061_50610101_4_dialog_content = "Ini adalah peristiwa anomali terkait Aurora yang jarang tercatat dalam sejarah Northland, dan legenda Roh Aurora telah bertahan untuk waktu yang lama sejak itu.",
  ui_story_5061_50610101_5_dialog_content = "Aurorian terlahir bergantung pada Lumina, dan Aurora hanya muncul ketika Lumina padat memenuhi kondisi tertentu dalam lingkungan yang diberikan.",
  ui_story_5061_50610101_6_dialog_content = "Ini adalah manifestasi ekstrem dari energi mentah... mungkin bentuk terbersih dari Lumina!",
  ui_story_5061_50610101_7_dialog_content = "Ini memanggil semua Aurorian seperti mercusuar di malam hari, menjadi simbol eksistensi mereka.",
  ui_story_5061_50610101_8_dialog_content = "Tentu saja, fenomena langka seperti ini pasti akan menarik rasa kagum dan keingintahuan orang... Dan aku pun tidak berbeda!",
  ui_story_5061_50610101_9_dialog_content = "Ada banyak teori mengenai asal-usul Aurora. Teori Kegelapan Zona Turbulensi, teori Cahaya Suci, teori Fragmentasi Kutub, teori Badai Elektromagnetik...",
  ui_story_5061_50610101_10_dialog_content = "Tapi secara pribadi, saya percaya teori Sumber Daya Kuno adalah yang paling masuk akal.",
  ui_story_5061_50610101_11_dialog_content = "Aurora memiliki jumlah kekuatan yang tak terbayangkan, yang kemungkinan besar dimanfaatkan oleh peradaban kuno yang tersembunyi tepat di bawah kaki kita.",
  ui_story_5061_50610101_12_dialog_content = "Teks Lumopolis menunjukkan bahwa Aurora pertama kali muncul dari serangkaian reruntuhan kuno. Namun, reruntuhan spesifik itu sendiri masih diperdebatkan.",
  ui_story_5061_50610101_13_dialog_content = "Jika hipotesis ini benar, akankah saya menemukan asal mula Aurora yang sebenarnya di akhir perjalanan saya?",
  ui_story_5061_50610101_14_dialog_content = "...",
  ui_story_5061_50610101_15_dialog_content = "Sekarang pukul 22:14. Saya percaya sekarang saya sudah melampaui perbatasan Northland, serta jangkauan perlindungan Beacon.",
  ui_story_5061_50610101_16_dialog_content = "Aku melihat beberapa sosok gelap berdiri tegak di dataran beku. Mungkin sisa-sisa pohon kuno, atau mungkin...",
  ui_story_5061_50610101_17_dialog_content = "...",
  ui_story_5061_50610101_18_dialog_content = "Untuk menghindari deteksi Eclipsite, sekarang saya akan mematikan perangkat perekam.",
  ui_story_5061_50610101_19_dialog_content = "Jika ada yang menemukan rekaman ini, itu berarti nasib saya berubah menjadi lebih buruk. Jika itu terjadi, tolong antarkan ini ke Northland Court.",
  ui_story_5061_50610101_20_dialog_content = "Saya sangat berharap bahwa generasi mendatang akan menemukan penelitian saya berguna dalam mengungkap asal-usul Aurora.",
  ui_story_5061_50610101_21_dialog_content = "Sehingga suatu hari nanti, kita akhirnya bisa memahami...",
  ui_story_5061_50610101_22_dialog_content = "Dari mana asal Aurorian, dan dunia seperti apa yang kita tempati.",
  ui_story_5061_50610101_23_dialog_content = "... Ah! Apakah itu—?!",
  ui_story_5061_50610101_24_dialog_content = "Di dalam es, itu... seorang manusia?!",
  ui_story_5061_50610101_25_dialog_content = "... Seorang pengembara yang terdampar? Atau mungkin... Apakah ini bisa jadi Roh Aurora legendaris?",
  ui_story_5061_50610101_26_dialog_content = "... Apakah dia masih hidup?",
  ui_story_5061_50610201_1_dialog_content = "(Menghela nafas) Akhirnya aku berhasil!",
  ui_story_5061_50610201_2_dialog_content = "Saljunya semakin tebal! Aku harus kembali ke dalam Colossus!",
  ui_story_5061_50610201_3_dialog_content = "Gosok-gosokkan tangan Anda dan hembuskan napas ke dalamnya...",
  ui_story_5061_50610201_4_dialog_content = "Haaah—Haaaaah—",
  ui_story_5061_50610201_5_dialog_content = "Tidak ada gunanya! Meskipun aku melakukan itu, tanganku masih saja dingin!",
  ui_story_5061_50610201_6_dialog_content = "Haha, yah, kamu memang berada di Northland, toh...",
  ui_story_5061_50610201_7_dialog_content = "Kalau tahu bakal se-dingin ini, seharusnya aku membawa perlengkapan bertahan musim dingin yang lebih lengkap untuk pekerjaan ini!",
  ui_story_5061_50610201_8_dialog_content = "Memang, jika Carleen ada di sekitar, dia pasti akan mengingatkan kamu.",
  ui_story_5061_50610201_9_dialog_content = "Sebenarnya, dia mungkin sudah membuatkanmu secangkir teh hangat yang enak sekarang!",
  ui_story_5061_50610201_10_dialog_content = "(Menghela napas) Aku sudah merindukan kembali ke Lumopolis dan Illumina bersama semua orang! Setidaknya aku tidak akan kedinginan sampai mati.",
  ui_story_5061_50610201_11_dialog_content = "Maaf kami tidak bisa pergi bersamamu kali ini...",
  ui_story_5061_50610201_12_dialog_content = "Tapi aku berjanji kita akan bersenang-senang di Northland bersama lain kali!",
  ui_story_5061_50610201_13_dialog_content = "Dan jika Carleen ikut, dia bahkan mungkin mengajak kita naik kereta kuda!",
  ui_story_5061_50610201_14_dialog_content = "(Jika ada kesempatan berikutnya, aku lebih memilih tinggal di Colossus-ku...)",
  ui_story_5061_50610201_15_dialog_content = "Tidak apa-apa, sungguh. Aku hanya sedikit bosan di sini, dan aku tidak bisa memikirkan hal lain untuk dibicarakan.",
  ui_story_5061_50610201_16_dialog_content = "Saya tahu. Mudah untuk merasa kesepian saat Anda bepergian sendirian melewati salju. Mengapa tidak mencoba komunikator baru yang diberikan oleh Petugas Gronru kepada Anda?",
  ui_story_5061_50610201_17_dialog_content = "Colossus ini menangkap berbagai macam suara dan sinyal dari seluruh dunia. Bahkan jika kamu sendirian di Colossus, saya yakin itu akan membantu mencerahkan suasana hati untukmu!",
  ui_story_5061_50610201_18_dialog_content = "Kamu mungkin bisa mendengar suara mesin dari Illumina, atau bahkan siaran musik dari Umbraton! Menakjubkan, bukan?",
  ui_story_5061_50610201_19_dialog_content = "... Lebih luar biasa lagi jika aku bisa memilih apa yang ingin didengarkan...",
  ui_story_5061_50610201_20_dialog_content = "Tebak kamu harus percaya pada Petugas Gronru!",
  ui_story_5061_50610201_21_dialog_content = "Pastikan untuk menjaga dirimu dengan baik di luar sana. Dan jika kamu melihat sesuatu yang menarik, ingatlah untuk memberi tahu kami agar kita bisa melihatnya bersama suatu hari nanti!",
  ui_story_5061_50610201_22_dialog_content = "Pokoknya, selama Queen Bethlehem ada di sekitar, Northland seharusnya aman-aman saja. Kalau tidak, aku nggak akan pernah merasa baik-baik saja meninggalkan kamu sendirian!",
  ui_story_5061_50610201_23_dialog_content = "Nah, pelatihan akan segera dimulai, jadi aku harus pergi. Sampai berbicara lagi!",
  ui_story_5061_50610201_24_dialog_content = "Oke.",
  ui_story_5061_50610201_25_dialog_content = "...",
  ui_story_5061_50610201_26_dialog_content = "Karena waktu dan tempatnya salah?",
  ui_story_5061_50610201_26X1_dialog_content = "Northland memang benar-benar... Persis seperti yang Carleen dan yang lain gambarkan...",
  ui_story_5061_50610201_27_dialog_content = "Northland saat ini tidak lagi menyerupai dongeng yang mempesona yang pernah Carleen ceritakan padaku...",
  ui_story_5061_50610201_27X1_dialog_content = "Ini benar-benar berbeda dari tempat-tempat seperti Lumopolis dan Undercities.",
  ui_story_5061_50610201_28_dialog_content = "<color=#e8d9bb>Luas, dingin, dan misterius, hutan-hutan terbentang tak berujung sementara puncak gunung menjulang tinggi, megah dan anggun.</color>",
  ui_story_5061_50610201_29_dialog_content = "<color=#e8d9bb>Jejak peradaban di tanah ini sangat sedikit, seolah tidak ada perubahan sama sekali selama ribuan tahun berlalu.</color>",
  ui_story_5061_50610201_30_dialog_content = "Di sini sunyi sekali...",
  ui_story_5061_50610201_31_dialog_content = "... Mungkin aku harus mencoba komunikator Gronru. Apapun untuk menghancurkan keheningan yang berat ini.",
  ui_story_5061_50610201_32_option_content = "Aktifkan Communicator",
  ui_story_5061_50610201_33_dialog_content = "(Klik) Nguung, nguung...",
  ui_story_5061_50610201_34_dialog_content = "Dengung, dengung...",
  ui_story_5061_50610201_35_dialog_content = "...Sama sekali tidak berfungsi!",
  ui_story_5061_50610201_36_dialog_content = "Semua statis ini bikin pusing. Kayaknya aku harus mematikannya...",
  ui_story_5061_50610201_37_dialog_content = "... A... Ada orang?!",
  ui_story_5061_50610201_38_dialog_content = "... Ini adalah... yang... Meminta tolong!",
  ui_story_5061_50610201_39_dialog_content = "Hah? Panggilan darurat?!",
  ui_story_5061_50610201_40_dialog_content = "Saya ulangi: Ini adalah punggungan timur laut dari Puncak Cedar di perbatasan Northland, dengan ketinggian 3.200 meter.",
  ui_story_5061_50610201_41_dialog_content = "Aku menemukan seseorang terjebak dalam es. Situasinya terlihat buruk, dan aku tidak bisa melakukan penyelamatan.",
  ui_story_5061_50610201_42_dialog_content = "Siapa pun yang mungkin mendengar, harap datang dengan membawa alat pemecah es dan peralatan pemanas untuk penyelamatan!",
  ui_story_5061_50610201_43_dialog_content = "Cedar Peak... Itu tidak jauh dari sini sama sekali!",
  ui_story_5061_50610201_44_dialog_content = "Bertahanlah! Bantuan sedang dalam perjalanan!",
  ui_story_5061_50610201_45_dialog_content = "(Cuaca dan medan membuatnya sulit untuk mendarat dengan cepat... Semoga saja aku tidak terlambat.)",
  ui_story_5061_50610201_46_dialog_content = "Halo? Ada orang di sana? Saya menerima panggilan darurat dari lokasi ini!",
  ui_story_5061_50610201_47_dialog_content = "Hai! Ada yang bisa mendengarku?! Kayaknya aku harus menggunakan kekuatanku... Gaya Boo—Whoa!",
  ui_story_5061_50610201_48_dialog_content = "(Saljunya sangat dalam! Dan yang terlihat hanya salju terus-menerus... Apakah mereka tertimbun di bawah semua itu?!)",
  ui_story_5061_50610201_49_dialog_content = "<color=#e8d9bb>Kegentingan-</color>",
  ui_story_5061_50610201_50_dialog_content = "Apa katamu?",
  ui_story_5061_50610201_51_dialog_content = "<color=#e8d9bb>Berkeritik—</color>",
  ui_story_5061_50610201_52_dialog_content = "Ha…",
  ui_story_5061_50610201_53_dialog_content = "Suara apa itu... Apakah ada seseorang yang benar-benar terkubur di salju?!",
  ui_story_5061_50610201_54_dialog_content = "Bertahanlah, aku akan mengeluarkanmu dari sana!!",
  ui_story_5061_50610201_55_dialog_content = "Haah... Haah...",
  ui_story_5061_50610201_56_dialog_content = "Roaar—",
  ui_story_5061_50610201_57_dialog_content = "Hah?!?!",
  ui_story_5061_50610201_58_dialog_content = "Mengaktifkan teknik darurat!",
  ui_story_5061_50610201_59_dialog_content = "Gaaah!",
  ui_story_5061_50610201_60_dialog_content = "Berlindunglah di belakangku! Aku akan menghadapi hal ini!",
  ui_story_5061_50610202_1_dialog_content = "Groar...",
  ui_story_5061_50610202_2_dialog_content = "Fiuh, aku selamat. Terima kasih...",
  ui_story_5061_50610202_3_dialog_content = "Permisi, tapi kamu pasti...",
  ui_story_5061_50610202_4_dialog_content = "Warna! Saya melihat Lumina dalam berbagai warna saat pertempuran tadi! Mereka sangat jelas seperti siang hari!",
  ui_story_5061_50610202_5_dialog_content = "Seolah-olah jalan menuju kemenangan muncul dalam pikiran saya... Saya tahu persis apa yang harus saya lakukan!",
  ui_story_5061_50610202_6_dialog_content = "Aku bergerak mengikuti aliran Lumina seperti daun yang terbawa angin. Semuanya terasa begitu alami...",
  ui_story_5061_50610202_7_dialog_content = "Tapi bagaimana? Bagaimana bisa?! Aku harus tahu lebih banyak tentang ini! Aku harus!!!",
  ui_story_5061_50610202_8_dialog_content = "Kamu pasti Caelestite yang baru saja aku dengar! Bisakah kamu menjawab beberapa pertanyaan dariku? Aku ingin tahu lebih banyak tentang kemampuanmu, dan tentang pengalamanmu mengemudikan Colossus!",
  ui_story_5061_50610202_9_dialog_content = "T-Tunggu sebentar! Saya senang untuk berbicara, tapi seharusnya kita saling memperkenalkan diri dulu, bukan? Nama saya PlayerName.",
  ui_story_5061_50610202_10_dialog_content = "Oh! M-maaf ya, kadang-kadang aku suka terlalu bersemangat... Ini kebiasaan burukku, tapi semoga aku tidak membuatmu merasa tidak nyaman atau apa pun ya?",
  ui_story_5061_50610202_11_dialog_content = "Namaku Antony, dan aku seorang ahli folklor. Apakah kamu datang karena panggilan darurat yang kusampaikan?",
  ui_story_5061_50610202_12_dialog_content = "Cuaca di sini sangat ekstrem sehingga aku terkubur dalam salju. Yang bisa kulakukan hanyalah duduk dan menunggu sampai aku mendengar pertolongan mendekat...",
  ui_story_5061_50610202_13_dialog_content = "Syukurlah aku berhasil mendengar kedatanganmu!",
  ui_story_5061_50610202_14_dialog_content = "Benar. Saya juga sebenarnya tidak cocok untuk lingkungan seperti ini. Saya tidak bisa merasakan siapa pun di sini, pikir saya sedang menyelamatkan seseorang, yang ternyata malah Eclipsite...",
  ui_story_5061_50610202_15_dialog_content = "Ngomong-ngomong, kamu juga menyebutkan sesuatu tentang seseorang yang terjebak, bukan?",
  ui_story_5061_50610202_16_dialog_content = "Benar! Tapi situasinya ... agak sulit dipercaya. Ini benar-benar berbeda dari yang saya pikirkan sebelumnya ...",
  ui_story_5061_50610202_17_dialog_content = "Di sini, ikuti aku.",
  ui_story_5061_50610202_18_dialog_content = "Oh, dan hati-hati dengan stalaktit es itu. Beberapa di antaranya memiliki Eclipsites terjebak di dalamnya.",
  ui_story_5061_50610202_19_dialog_content = "Tapi ada banyak sekali...",
  ui_story_5061_50610202_20_dialog_content = "Ini dia. Ayo, lihatlah di dalam es.",
  ui_story_5061_50610202_21_dialog_content = "Apakah itu... seorang gadis, di dalam es?",
  ui_story_5061_50610202_22_dialog_content = "... Dia masih hidup?!",
  ui_story_5061_50610202_23_dialog_content = "Kurasa begitu, ya.",
  ui_story_5061_50610202_24_dialog_content = "Meskipun terjebak dalam es, tubuhnya tidak menunjukkan tanda-tanda terlihat bahwa dia membeku sampai mati.",
  ui_story_5061_50610202_25_dialog_content = "Faktanya, sepertinya dia hanya tidur. Seolah-olah kuburan beku ini tidak berbeda dengan tempat tidur...",
  ui_story_5061_50610202_26_dialog_content = "Mungkin aku bisa terhubung dengannya lewat telepati!",
  ui_story_5061_50610202_27_option_content = "Force Boost",
  ui_story_5061_50610202_28_dialog_content = "Nng... Hah...?",
  ui_story_5061_50610202_29_dialog_content = "Kapan aku... tertidur...?",
  ui_story_5061_50610202_30_dialog_content = "Bagaimana ini bisa terjadi? Aku punya... sesuatu yang penting untuk dilakukan...",
  ui_story_5061_50610202_31_dialog_content = "Jika aku gagal... Semua desa di sekitarnya, tidak, seluruh Northland... Saudariku!!!",
  ui_story_5061_50610202_32_dialog_content = "Dia benar-benar masih hidup! Dan pikirannya juga bereaksi sangat intens!",
  ui_story_5061_50610202_33_dialog_content = "Itu luar biasa! Haruskah kita mencoba membebaskannya dari es? Atau mungkin langkah terbaik kita adalah mencairkannya terlebih dahulu...",
  ui_story_5061_50610202_34_dialog_content = "Tunggu, aku merasakan fluktuasi energi aneh di sekitar...",
  ui_story_5061_50610202_35_dialog_content = "Dan sepertinya dia adalah sumbernya. Dia pasti memiliki jumlah Lumina yang sangat besar tersimpan di dalam tubuhnya...",
  ui_story_5061_50610202_36_dialog_content = "Dan ketika saya membangunkannya dengan kekuatan saya, dia mulai menggunakan Luminatics-nya secara bawah sadar!",
  ui_story_5061_50610202_37_dialog_content = "<color=#e8d9bb>(Suara retakan)</color>",
  ui_story_5061_50610202_38_dialog_content = "Kedengarannya seperti es mulai terbelah.",
  ui_story_5061_50610202_39_dialog_content = "Lumina yang menciptakan es ini mengalir keluar dengan cepat. Dengan kecepatan ini, dia mungkin bisa melepaskan diri. Ini bagus!",
  ui_story_5061_50610202_40_dialog_content = "Hebat, kakiku! Bagaimana jika dia memicu longsoran salju atau semacamnya?!",
  ui_story_5061_50610202_41_dialog_content = "Kita perlu mundur ke jarak yang aman sebelum kita terkubur bersama Eclipsite lainnya!",
  ui_story_5061_50610202_42_dialog_content = "Roaar—",
  ui_story_5061_50610202_43_dialog_content = "Hanya itu yang diperlukan untuk membebaskan mereka?!",
  ui_story_5061_50610202_44_dialog_content = "Oh tidak... Mereka menuju langsung ke arah kita!",
  ui_story_5061_50610202_45_dialog_content = "Eclipsite benar-benar makhluk yang menarik. Jika hidup kita tidak begitu berbahaya, aku ingin mempelajarinya lebih dekat...",
  ui_story_5061_50610202_46_dialog_content = "<color=#e8d9bb>(Dengus)</color>",
  ui_story_5061_50610202_47_dialog_content = "Untungnya, jumlah mereka tidak terlalu banyak. Aku harus bisa menarik perhatian mereka sementara kamu melarikan diri.",
  ui_story_5061_50610202_48_dialog_content = "Kamu akan melawan mereka semua sendirian?! Mereka tidak begitu tertarik dengan penelitianmu, tahu!",
  ui_story_5061_50610202_49_dialog_content = "Jangan khawatir. Sebagai setengah manusia, saya lebih dari mampu menjaga diri sendiri. Lagipula, saya sudah mengalami situasi seperti ini berkali-kali.",
  ui_story_5061_50610202_50_dialog_content = "Setidaknya, aku harus bisa bertahan dari serangan mereka sampai mereka kelelahan.",
  ui_story_5061_50610202_51_dialog_content = "Itu... strategi yang sangat unik.",
  ui_story_5061_50610202_52_dialog_content = "Tapi karena aku di sini, aku akan melakukan segala yang bisa aku lakukan untuk membantumu menang. Aku seorang Caelestite, aku tidak akan mengecewakanmu.",
  ui_story_5061_50610202_53_dialog_content = "Aku mendukungmu! Mari tunjukkan pada monster-monster ini apa yang terjadi saat kita mengikuti aliran Lumina!",
  ui_story_5061_50610202_54_dialog_content = "Roaar—!",
  ui_story_5061_50610202_55_dialog_content = "Argh! A-Aku belum selesai...",
  ui_story_5061_50610202_56_dialog_content = "Fokus, Antony! Kamu perlu mengikuti jalan Lumina di kakimu—Hah?",
  ui_story_5061_50610202_57_dialog_content = "K-Kakiku... mereka membeku?!",
  ui_story_5061_50610202_58_dialog_content = "Suhu turun drastis...",
  ui_story_5061_50610202_59_dialog_content = "Siapa... di sana?",
  ui_story_5061_50610202_60_dialog_content = "Graagh!",
  ui_story_5061_50610302_1_dialog_content = "Woah!",
  ui_story_5061_50610302_2_dialog_content = "Badai salju akhirnya mereda... Apakah kamu baik-baik saja?",
  ui_story_5061_50610302_3_dialog_content = "Aku baik-baik saja, tapi bagaimana dengannya...?",
  ui_story_5061_50610302_4_dialog_content = "...",
  ui_story_5061_50610302_5_dialog_content = "Hati-hati!",
  ui_story_5061_50610302_6_dialog_content = "Denyut nadi dan pernapasannya normal, tapi dia sedingin es dan wajahnya terlihat sedikit pucat...",
  ui_story_5061_50610302_7_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5061_50610302_8_dialog_content = "Bangunkan dia dan coba pertahankan kesadarannya. Aku akan mencari jalur ke desa terdekat.",
  ui_story_5061_50610302_9_dialog_content = "Bukan masalah.",
  ui_story_5061_50610302_10_dialog_content = "Maaf jika ini terasa agak paksa... Tapi cara terbaik untuk membangunkanmu sepenuhnya adalah dengan memasuki pikiranmu lagi!",
  ui_story_5061_50610302_11_dialog_content = "Bangun!!!",
  ui_story_5061_50610302_12_dialog_content = "Ah?!",
  ui_story_5061_50610302_13_option_content = "Eh, hai... Kamu baik-baik saja?",
  ui_story_5061_50610302_14_dialog_content = "Maaf telah membangunkanmu seperti itu. Apakah kamu terluka sama sekali? Apakah kamu ingat sesuatu?",
  ui_story_5061_50610302_15_dialog_content = "Siapa kamu? A-aku belum pernah melihatmu sebelumnya dalam hidupku...",
  ui_story_5061_50610302_16_option_content = "Hmm, aneh sekali.",
  ui_story_5061_50610302_17_dialog_content = "Apakah kamu semacam dewi es lilin? Kekuatan yang kamu keluarkan tadi itu gila!",
  ui_story_5061_50610302_18_dialog_content = "M-Maksudmu, dewi es loli?",
  ui_story_5061_50610302_19_dialog_content = "Siapa kamu, dan apa yang kamu bicarakan?!",
  ui_story_5061_50610302_20_dialog_content = "Nah, nama saya PlayerName, dan saya seorang Caelestite. Saya dan teman saya menemukan kamu terjebak dalam es...",
  ui_story_5061_50610302_21_dialog_content = "... Setidaknya kamu terjebak, tapi kemudian kamu berhasil keluar dari situ hanya beberapa menit yang lalu.",
  ui_story_5061_50610302_22_dialog_content = "Bagaimana perasaanmu? Apakah ada yang sakit?",
  ui_story_5061_50610302_23_dialog_content = "Seorang Caelestite...? Apa yang dilakukan Caelestite di sini...",
  ui_story_5061_50610302_24_dialog_content = "Es... Aku ingat berjuang melawan gerombolan Eclipsites, tapi kemudian...",
  ui_story_5061_50610302_25_dialog_content = "Tunggu... Apa aku mati? Mungkinkah tempat ini adalah kehidupan setelah mati...?",
  ui_story_5061_50610302_26_dialog_content = "... Salah semua perkiraan. Kita berada di gunung dekat perbatasan Northland, dan kita masih sangat hidup.",
  ui_story_5061_50610302_27_dialog_content = "Sebuah gunung di dekat perbatasan Northland... Benar! Saya datang ke sini mencari saudara perempuan saya!",
  ui_story_5061_50610302_28_dialog_content = "<color=#FFB400>Kak</color>... Katakan padaku, apakah mereka juga berhasil menyelamatkan <color=#FFB400>patroller</color> lainnya?",
  ui_story_5061_50610302_29_dialog_content = "Maksud kamu masih ada orang lain yang terjebak di dalam es?",
  ui_story_5061_50610302_30_dialog_content = "Tidak, yang kumaksud adalah...",
  ui_story_5061_50610302_31_dialog_content = "Tunggu, maksud kamu kamu tidak tahu?! Ini adalah tempat di mana <color=#FFB400>Badai Aurora</color> terjadi! Pengadilan mengirimkan puluhan petugas patroli untuk menyelidiki!",
  ui_story_5061_50610302_32_dialog_content = "Kecuali... Tidak ada satupun dari mereka yang kembali. Apakah Anda yakin tidak melihat orang lain?",
  ui_story_5061_50610302_33_dialog_content = "(Saya tidak tahu apa-apa tentang ini saat datang ke Northland... Antony juga tidak menyebutkan apa-apa.)",
  ui_story_5061_50610302_34_dialog_content = "Namaku Zarya. Adikku, Alina, dia kapten patroli. Katakan padaku, apa kau benar-benar tidak melihat orang lain di sini?",
  ui_story_5061_50610302_35_dialog_content = "Aku sangat minta maaf, tapi aku belum melihat... Tunggu, apa itu?!",
  ui_story_5061_50610302_36_dialog_content = "Roaar—",
  ui_story_5061_50610302_37_dialog_content = "(Sial! Aku terlalu asyik berbicara dengannya. Aku sama sekali lupa mengawasi sekitar kita!)",
  ui_story_5061_50610302_38_dialog_content = "... Mekarlah, Frostlight!",
  ui_story_5061_50610302_39_dialog_content = "Ugh—",
  ui_story_5061_50610302_40_dialog_content = "(Sangat kuat... Meskipun dia tidak dalam kekuatan penuh, dia berhasil mengalahkan empat Eclipsite hanya dengan satu serangan!)",
  ui_story_5061_50610302_41_dialog_content = "Ada Eclipsites di sini... Itu berarti adikku dalam bahaya yang lebih besar!",
  ui_story_5061_50610302_42_dialog_content = "Aku.. Aku harus segera menemukannya! Alina!",
  ui_story_5061_50610302_43_dialog_content = "Tunggu! Kamu baru saja bangun tidak lama ini! Terlalu berbahaya untuk bertarung dalam kondisi seperti ini!",
  ui_story_5061_50610302_44_dialog_content = "Tapi kakakku juga bisa dalam bahaya!",
  ui_story_5061_50610302_45_dialog_content = "Aku tidak mengerti bagaimana atau mengapa, tapi akhirnya aku punya cara untuk melawan Eclipsites sekarang!",
  ui_story_5061_50610302_46_dialog_content = "Jika aku tidak bisa menyelamatkan keluargaku dengan kekuatan ini, lalu apa gunanya aku—",
  ui_story_5061_50610302_47_dialog_content = "<color=#e8d9bb>Celepuk!</color>",
  ui_story_5061_50610302_48_dialog_content = "Hei! Sadarlah! Tidak akan ada harapan untukmu jika kamu pingsan di tempat seperti ini!",
  ui_story_5061_50610302_49_dialog_content = "J-Jika sesuatu terjadi padaku, tolong... Bantu aku menemukan saudariku, dan beritahu dia, katakan padanya bahwa aku tidak ingin ditinggalkan lagi.",
  ui_story_5061_50610302_50_dialog_content = "...",
  ui_story_5061_50610302_51_dialog_content = "Hei—!",
  ui_story_5061_50610302_52_dialog_content = "Nafas Musim Semi—",
  ui_story_5061_50610302_53_dialog_content = "Ini... kuncup bunga? Dan kenapa tiba-tiba aku merasa sangat nyaman...?",
  ui_story_5061_50610302_54_dialog_content = "Maaf, tapi apakah kamu PlayerName?",
  ui_story_5061_50610302_55_dialog_content = "Ya, itu aku.",
  ui_story_5061_50610302_56_dialog_content = "Um, h-halo... Namaku Leah, dan aku petugas patroli Northland... M-maksudku, seorang petugas patroli yang sedang dalam pelatihan.",
  ui_story_5061_50610302_57_dialog_content = "Tuan Antony meminta saya untuk memimpin semua orang menuju tempat yang aman.",
  ui_story_5061_50610302_58_dialog_content = "T-Tenang saja, saya sangat mengenal jalur pegunungan dan tempat persembunyian di daerah ini. Saya bersumpah untuk membimbing semua orang kembali ke jangkauan perlindungan Queen Bethlehem dengan aman.",
  ui_story_5061_50610302_59_dialog_content = "Um, itu semuanya, kukira. Apakah aku melewatkan sesuatu?",
  ui_story_5061_50610401_1_dialog_content = "Ini, cicipi buah yang baru saja dipetik...",
  ui_story_5061_50610401_2_dialog_content = "Sangat baik untuk melawan dingin.",
  ui_story_5061_50610401_3_dialog_content = "Maksud saya ingin membawa lebih banyak obat dan perbekalan, tetapi stok kami sangat terbatas saat ini. Saya minta maaf...",
  ui_story_5061_50610401_4_dialog_content = "Tidak perlu minta maaf untuk itu, kami sudah sangat berterima kasih atas bantuanmu. Apakah kamu tidak ingin mencoba, Antony?",
  ui_story_5061_50610401_5_dialog_content = "Oh! Maaf, tadi saya tidak memperhatikan.... Terima kasih.",
  ui_story_5061_50610401_6_dialog_content = "Jadi, bagaimana kabar Zarya?",
  ui_story_5061_50610401_7_dialog_content = "Seperti yang kamu katakan sebelumnya, kondisinya jauh dari normal. Aku juga mendeteksi jumlah Lumina yang sangat besar di dalam tubuhnya.",
  ui_story_5061_50610401_8_dialog_content = "Sejujurnya, seorang Aurorian biasa tidak akan mampu menanggung Lumina sebanyak ini.",
  ui_story_5061_50610401_9_dialog_content = "Namun, tidak hanya mampu bertahan dalam keadaan terbungkus es, dia juga berhasil keluar dari es tersebut sendiri. Itu bukan hal biasa.",
  ui_story_5061_50610401_10_dialog_content = "Memang. Aku juga sama terkejutnya saat mengetahui dia masih hidup ketika aku menyelidiki pikirannya.",
  ui_story_5061_50610401_11_dialog_content = "Berbicara dengannya memang tidak mudah. Dia terus membahas tentang petugas patroli dan saudarinya, serta sesuatu tentang \"Aurorastorm\"...",
  ui_story_5061_50610401_12_dialog_content = "Dia tidak mau mendengarkan satu kata pun yang kukatakan.",
  ui_story_5061_50610401_13_dialog_content = "Para petugas patroli baik-baik saja, dan tidak ada yang hilang akhir-akhir ini, kan, Leah?",
  ui_story_5061_50610401_14_dialog_content = "Oh! A-Apakah kamu berbicara denganku...?",
  ui_story_5061_50610401_15_dialog_content = "Ya, kamu benar. Setiap petugas patroli telah kembali dari pos mereka, selamat dan sehat.",
  ui_story_5061_50610401_16_dialog_content = "Itu sesuai dengan pemahaman saya juga. Ini adalah Northland, setelah semua; selama kita tetap berada di dalam batasnya, kita seharusnya aman-aman saja.",
  ui_story_5061_50610401_17_dialog_content = "Semua orang tahu itu. Dalam keadaan darurat, kita semua tahu untuk mundur ke wilayah Queen demi keselamatan.",
  ui_story_5061_50610401_18_dialog_content = "Aku ingin bertanya.",
  ui_story_5061_50610401_19_dialog_content = "Beacon of Northland... Dapatkah itu benar-benar melindungi seluruh Northland hanya dengan kekuatan Queen Bethlehem?",
  ui_story_5061_50610401_19X1_dialog_content = "Sejak kunjungan pertama saya ke Northland, saya menyadari bahwa semua orang terus membicarakan perlindungan yang diberikan oleh Queen dan Beacon.",
  ui_story_5061_50610401_20_dialog_content = "Setelah kunjungan terakhirku ke Winter Palace, aku tak henti-hentinya khawatir tentang kesejahteraannya.",
  ui_story_5061_50610401_20X1_dialog_content = "Aku tahu Queen Bethlehem adalah salah satu Aurorian yang paling mulia dan kuat di seluruh Astra.",
  ui_story_5061_50610401_21_dialog_content = "Dia bilang bahwa bagian terburuk sudah berlalu, dan aku tak perlu khawatir lagi... Tapi, apakah dia benar-benar baik-baik saja?",
  ui_story_5061_50610401_21X1_dialog_content = "Dan apa yang membuat Beacon begitu istimewa? Apakah benar-benar mampu melindungi seluruh bangsa dengan penghalang pelindung?",
  ui_story_5061_50610401_22_dialog_content = "Yang Mulia Ratu adalah... orang yang paling bisa dipercaya dan diandalkan yang saya kenal! Jika dia mengatakan sesuatu, maka itu pasti benar!",
  ui_story_5061_50610401_22X1_dialog_content = "Dan ya, itu benar-benar istimewa! Selama Beacon tetap menyala, tidak ada Eclipsite yang bisa masuk ke Northland.",
  ui_story_5061_50610401_23_dialog_content = "Saya yakin ada lebih banyak hal tentang Beacon daripada itu. Bagaimanapun, sebagai pertahanan utama kita melawan Eclipsites selama lebih dari satu milenium, pasti ada berbagai macam rahasia yang terkandung di dalam dindingnya.",
  ui_story_5061_50610401_23X1_dialog_content = "Singkatnya, Beacon adalah struktur pertahanan unik dari Northland, sama seperti Lumopolis dan Illumina memiliki struktur mereka sendiri.",
  ui_story_5061_50610401_24_dialog_content = "Sebagai penduduk Northland, sepenuh hati percaya pada Ratu kita adalah langkah pertama untuk membantunya.",
  ui_story_5061_50610401_24X1_dialog_content = "Beacon adalah senjata terbesar kita, sekaligus pertahanan terkuat kita.",
  ui_story_5061_50610401_25_dialog_content = "Namun, aku jauh lebih tertarik pada Aurorastorm...",
  ui_story_5061_50610401_26_dialog_content = "Apakah kamu yakin Nona Zarya yang mengatakannya?",
  ui_story_5061_50610401_27_dialog_content = "Ya, dan aku juga ingat dengan jelas. Dia bertekad untuk menemukan saudara perempuannya dan patroli lainnya, itulah mengapa dia datang ke sini pada awalnya.",
  ui_story_5061_50610401_28_dialog_content = "Tapi selain apa yang terjadi padanya, tidak ada hal lain di area ini yang tampak tidak biasa.",
  ui_story_5061_50610401_29_dialog_content = "Mengerti. Hal ini mengkhawatirkan karena akhir-akhir ini saya sedang mencari petunjuk yang berkaitan dengan Badai Aurora.",
  ui_story_5061_50610401_30_dialog_content = "Sebenarnya, itulah alasan utama saya datang ke Cedar Peak.",
  ui_story_5061_50610401_31_dialog_content = "Saya percaya langkah selanjutnya adalah melakukan survei menyeluruh di area ini. Hanya dengan begitu saya akan dapat menghasilkan kesimpulan yang lebih spesifik.",
  ui_story_5061_50610401_32_dialog_content = "Dengan keberuntungan, saya akan dapat mengetahui lebih banyak tentang situasi Miss Zarya!",
  ui_story_5061_50610401_33_dialog_content = "Kami mengandalkanmu, Antony. Saya juga ingin tahu lebih banyak tentang Lumina aneh yang saya rasakan darinya sebelumnya.",
  ui_story_5061_50610401_34_dialog_content = "Energi itu lebih murni daripada apa pun yang pernah aku alami...",
  ui_story_5061_50610401_35_dialog_content = "Baiklah. Tolong terus jaga dia dengan baik sementara aku mengumpulkan informasi lebih lanjut.",
  ui_story_5061_50610401_36_dialog_content = "Eh, apakah aku harus mencoba mencari dokter?",
  ui_story_5061_50610401_37_dialog_content = "Saya rasa itu tidak perlu. Sejauh yang saya tahu, dia tidak sakit atau terluka. Pertolongan pertama saya seharusnya cukup untuk saat ini.",
  ui_story_5061_50610401_38_dialog_content = "Kamu benar-benar tahu segalanya, Antony. Tidak hanya kuat bertarung, tapi kamu bahkan tahu cara memberikan perawatan medis!",
  ui_story_5061_50610401_39_dialog_content = "Saya juga penasaran untuk mengetahui lebih lanjut tentang penelitian Anda mengenai asal-usul Aurorian.",
  ui_story_5061_50610401_40_dialog_content = "Apakah Anda pernah belajar di Lumopolis atau Illumina, mungkin?",
  ui_story_5061_50610401_41_dialog_content = "Hmm? Sama sekali tidak, kenapa kamu bertanya?",
  ui_story_5061_50610401_42_dialog_content = "Oh, hanya saja seorang teman baik saya pernah kuliah di luar negeri, dan dia benar-benar belajar banyak saat itu. Saya hanya penasaran apakah Anda memiliki pengalaman serupa.",
  ui_story_5061_50610401_43_dialog_content = "Oh, begitu. Tidak, pendidikan formal yang saya dapatkan hanya dari kelas literasi yang ditawarkan untuk anak-anak di daerah perbatasan.",
  ui_story_5061_50610401_44_dialog_content = "Eh, kelas literasi?",
  ui_story_5061_50610401_45_dialog_content = "Benar! Berkat mereka, saya bisa membaca dan memahami buku, serta menuliskan temuan saya.",
  ui_story_5061_50610401_46_dialog_content = "Maaf jika aku mengecewakanmu, aku bukanlah seorang sarjana terkenal dari akademi bergengsi.",
  ui_story_5061_50610401_47_dialog_content = "Apa kamu bercanda? Justru itu lebih luar biasa!",
  ui_story_5061_50610401_48_dialog_content = "Saya juga tidak pernah menerima pendidikan formal di Astra. Semua pengetahuan saya diperoleh dari keluarga saya...",
  ui_story_5061_50610401_49_dialog_content = "Tapi kamu jauh lebih baik sebagai siswa daripada yang pernah bisa aku capai!",
  ui_story_5061_50610401_50_dialog_content = "Tidak ada yang salah dengan itu! Tidak masalah bagaimana atau di mana Anda memperoleh pengetahuan, selama keinginan tulus Anda untuk belajar dan menjelajah tetap ada!",
  ui_story_5061_50610401_51_dialog_content = "Aku akan pergi sekarang!",
  ui_story_5061_50610401_52_dialog_content = "Baik, hati-hati di luar sana.",
  ui_story_5061_50610401_53_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5061_50610401_54_dialog_content = "(Antony menutup pintu dengan sangat pelan... Mungkin untuk menghindari membangunkan Zarya.)",
  ui_story_5061_50610401_55_dialog_content = "(... Setelah berjuang dan bertarung di salju untuk waktu yang lama, kehangatan ruangan ini membuatku semakin mengantuk.)",
  ui_story_5061_50610401_56_dialog_content = "(Tampaknya Zarya tidak akan bangun dalam waktu dekat. Sepertinya aku harus mencoba untuk beristirahat juga.)",
  ui_story_5061_50610402_1_dialog_content = "(Huh? Kemana perginya Eclipsites itu? Terlalu panas di sini, dan mulutku sangat kering...)",
  ui_story_5061_50610402_2_dialog_content = "<color=#e8d9bb>Berkeritik—</color>",
  ui_story_5061_50610402_3_dialog_content = "(Oh... Ternyata hanya mimpi.)",
  ui_story_5061_50610402_4_dialog_content = "Apakah semuanya baik-baik saja? Nona Zarya?",
  ui_story_5061_50610402_5_dialog_content = "I-Ini tidak apa-apa! Aku hanya tidak tahu cara menggunakan ketel ini... Aku tidak menyadari kalau masih panas.",
  ui_story_5061_50610402_6_dialog_content = "Um, kamu adalah pasien, Nona Zarya. Aku pikir kamu harus berbaring lagi, tolong...",
  ui_story_5061_50610402_7_dialog_content = "Aku merasa baik-baik saja sekarang, janji! Lagipula, aku hanya mencoba menuangkan segelas air untuk orang ini...",
  ui_story_5061_50610402_8_dialog_content = "Hmm... Zarya, kamu sudah bangun? Sedang apa kalian berdua?",
  ui_story_5061_50610402_9_dialog_content = "Dan siapa yang menaruh jas ini padaku?",
  ui_story_5061_50610402_10_dialog_content = "Itu adalah ulah dari Nona Zarya. Ketika dia sadar, dia menemukan kamu sedang tidur di samping tempat tidurnya...",
  ui_story_5061_50610402_11_dialog_content = "Dia merasa sangat berhutang budi padamu karena kebaikanmu sehingga dia memintaku untuk membawakan mantel ini untukmu!",
  ui_story_5061_50610402_12_dialog_content = "S-saya tidak tahu apa yang Anda bicarakan. Maksud saya, ya, dia memang membantu saya sangat banyak di gunung tadi...",
  ui_story_5061_50610402_13_dialog_content = "Tapi aku juga menyelamatkannya dari sekumpulan Eclipsite yang haus darah. Pastinya itu membuat kita setara, kan...?",
  ui_story_5061_50610402_14_dialog_content = "L-Lagipula, sebagai orang luar, dia pantas diberikan sambutan Northland yang sebenarnya, bukan?!",
  ui_story_5061_50610402_15_dialog_content = "...",
  ui_story_5061_50610402_16_dialog_content = "M-Mungkin karena aku masih dalam pelatihan, aku tidak benar-benar mengerti apa yang baru saja kamu katakan, Nona Zarya...",
  ui_story_5061_50610402_17_dialog_content = "Ah! Tidak, itu tidak ada hubungannya! Hanya saja...",
  ui_story_5061_50610402_18_dialog_content = "Terima kasih.",
  ui_story_5061_50610402_19_dialog_content = "Aku menghargainya, tapi sebaiknya kamu benar-benar mencoba untuk tetap di tempat tidur dan beristirahat. Apakah kamu masih ingat apa yang terjadi di gunung itu?",
  ui_story_5061_50610402_20_dialog_content = "Aku memang. Aku akan mencari adikku, tapi kemudian kamu menghentikanku... Kenapa kamu melakukan itu?!",
  ui_story_5061_50610402_21_dialog_content = "Kalau tidak, kamu akan membeku lagi atau berada di perut Eclipsite. Apakah salah satu dari itu terdengar baik untukmu?",
  ui_story_5061_50610402_22_dialog_content = "Kamu sama sekali tidak mau mendengarkan, tapi pada akhirnya aku harus menggendongmu sepanjang jalan kembali.",
  ui_story_5061_50610402_23_dialog_content = "K-Kamu apa? Kamu membawaku turun gunung...?",
  ui_story_5061_50610402_24_dialog_content = "A-Aku mengerti... Tapi aku tak pernah memintamu melakukan itu, tahu! Aku akan baik-baik saja jika kau biarkan aku di luar sana!",
  ui_story_5061_50610402_25_dialog_content = "Sudahlah, bisa tidak? Kau terdengar seperti anak kecil sekarang!",
  ui_story_5061_50610402_26_dialog_content = "... Tetapi meskipun begitu, aku tahu aku harus membayarmu dengan layak karena telah menyelamatkan hidupku. Itu bukan sesuatu yang akan dikatakan oleh seorang anak, bukan?",
  ui_story_5061_50610402_27_dialog_content = "Baik, baik... Tapi jika ada yang pantas mendapat ucapan terima kasih, itu adalah Bapak Antony dan Leah. Mereka lah yang menemukan kalian dan membawakan obat.",
  ui_story_5061_50610402_28_dialog_content = "Iya, aku tahu.",
  ui_story_5061_50610402_29_dialog_content = "Sudah merasa lebih baik sekarang? Jika kamu siap menjawab beberapa pertanyaan, mungkin kita bisa mencari cara untuk menemukan adikmu.",
  ui_story_5061_50610402_30_dialog_content = "Tentu.",
  ui_story_5061_50610402_31_dialog_content = "Pertama-tama, apa yang kamu lakukan terjebak di es di atas sana?",
  ui_story_5061_50610402_32_dialog_content = "... Aku lebih baik tidak membicarakannya.",
  ui_story_5061_50610402_33_dialog_content = "Hei! Kamu baru saja setuju untuk membicarakan masalah ini, dan sekarang kamu mengingkari kata-kata kamu?!",
  ui_story_5061_50610402_34_dialog_content = "Y-Ya, kamu benar, maaf.",
  ui_story_5061_50610402_35_dialog_content = "Seperti yang pernah saya sebutkan sebelumnya, semua tim yang dikirim oleh Pengadilan untuk menyelidiki Aurorastorm tidak pernah terlihat atau terdengar lagi.",
  ui_story_5061_50610402_36_dialog_content = "Kakak perempuanku juga termasuk di antara mereka.",
  ui_story_5061_50610402_37_dialog_content = "Saya pergi ke lokasi terakhir mereka dan mencari selama berjam-jam. Akhirnya, saya berhasil mendengar suara adik perempuan saya di dekat sana, hanya untuk menemukan mereka sedang diserang oleh gerombolan Eclipsites.",
  ui_story_5061_50610402_38_dialog_content = "Banyak sekali mereka, dan saya khawatir saya tidak akan sampai pada kakak saya tepat waktu.",
  ui_story_5061_50610402_39_dialog_content = "Jadi, saat pertempuran berlangsung, aku bersembunyi di bawah tumpukan bangkai Eclipsite dan berdoa dengan sepenuh hati...",
  ui_story_5061_50610402_40_dialog_content = "Aku berdoa agar bisa menemukan kekuatan yang aku butuhkan untuk menyelamatkan adikku...",
  ui_story_5061_50610402_41_dialog_content = "Tiba-tiba, seolah doaku terkabul, kekuatan besar muncul di dalam diriku. Sayangnya, saya kehilangan kendali penuh atasnya, dan Lumina saya mengamuk di seluruh medan perang.",
  ui_story_5061_50610402_42_dialog_content = "Eclipsite hampir punah, tetapi pada saat yang sama, saya malah terjebak dalam kuburan beku yang dibuat oleh Luminatics saya sendiri.",
  ui_story_5061_50610402_43_dialog_content = "Di sana aku terlelap... Sampai kamu membangunkanku hari ini.",
  ui_story_5061_50610402_44_dialog_content = "Jadi kamu terperangkap dalam es, ya? Ceritamu semakin gila saja, tahu.",
  ui_story_5061_50610402_45_dialog_content = "B-Bukan karena aku ingin ini terjadi... Aku memang tidak terlalu pandai mengendalikan kekuatanku.",
  ui_story_5061_50610402_46_dialog_content = "Jadi, silakan tertawa! Selama kalian membantu saya menemukan adik saya setelah itu, kalian bisa tertawa sepuasnya...",
  ui_story_5061_50610402_47_dialog_content = "Aku masih kesulitan membedakan antara ingatanku dan kenyataan...",
  ui_story_5061_50610402_48_dialog_content = "Aku tahu.",
  ui_story_5061_50610402_49_dialog_content = "Leah, bisakah kamu ceritakan pada Zarya tentang apa yang kamu katakan padaku sebelumnya?",
  ui_story_5061_50610402_50_dialog_content = "S-Tentu saja!",
  ui_story_5061_50610402_51_dialog_content = "Ketika kami tiba di sini, PlayerName bertanya padaku... Apakah ada laporan keadaan darurat di area ini.",
  ui_story_5061_50610402_52_dialog_content = "Aku bilang kepadanya bahwa area ini sudah damai cukup lama sekarang, karena Eclipsites hanya ada di luar perbatasan Northland. Selain itu, setiap tim patroli telah melaporkan kembali ke istana tanpa ada insiden.",
  ui_story_5061_50610402_53_dialog_content = "Hal terdekat yang pernah kudengar tentang petugas patroli yang hilang adalah ketika salah satu dari kita bepergian sedikit lebih jauh dari biasanya. Ketika itu terjadi, kami hanya kehilangan kontak untuk beberapa waktu. Pertempuran hampir tidak pernah terjadi, dan kematian bahkan lebih jarang...",
  ui_story_5061_50610402_54_dialog_content = "Selain dari rumor tentang orang-orang yang mendengar \"Roh Aurora\" di dalam pegunungan, belum ada laporan aktivitas yang tidak biasa di area ini.",
  ui_story_5061_50610402_55_dialog_content = "Dengan kata lain, meskipun kami telah berusaha keras mengumpulkan informasi, kami belum mengetahui apa-apa yang berkaitan dengan saudara perempuan Anda atau patroli yang hilang.",
  ui_story_5061_50610402_56_dialog_content = "Ini berarti jika apa yang Anda katakan kepada kami benar, saudara perempuan Anda seharusnya sudah tiba di rumah dengan selamat dan sehat.",
  ui_story_5061_50610402_57_dialog_content = "Benarkah? Aku akan sangat lega jika itu benar...",
  ui_story_5061_50610402_58_dialog_content = "Mungkin jawabannya ada di suatu tempat di pikiranmu, Zarya.",
  ui_story_5061_50610402_59_dialog_content = "Hah? Ap-Apa maksudmu?",
  ui_story_5061_50610402_60_dialog_content = "Setelah menggabungkan pengamatan Antony dan temuan saya sendiri...",
  ui_story_5061_50610402_61_dialog_content = "Dugaan saya, Anda menghabiskan terlalu banyak waktu terjebak dalam lingkungan yang penuh dengan jenis Lumina yang aneh. Akibatnya, kenangan Anda sedikit kacau.",
  ui_story_5061_50610402_62_dialog_content = "Itulah mengapa kamu terus mencampuradukkan peristiwa masa lalu dengan kenyataan saat ini.",
  ui_story_5061_50610402_63_dialog_content = "M-Memori saya \"teracak\"?",
  ui_story_5061_50610402_64_dialog_content = "Dalam beberapa hal, ya. Saya rasa cara yang lebih baik untuk mengatakannya adalah bahwa semacam energi telah mempengaruhi otak Anda, sehingga sulit untuk memahami apa yang terjadi di sekitar Anda.",
  ui_story_5061_50610402_65_dialog_content = "Jadi, dengan kata lain, aku jadi lebih bodoh?!",
  ui_story_5061_50610402_66_dialog_content = "Mungkin kamu benar... Toh, alih-alih menyelamatkan adikku, aku malah terperangkap dalam es...",
  ui_story_5061_50610402_67_dialog_content = "Aku benar-benar tidak berguna... Aku tidak pikir ada orang bodoh yang lebih besar di dunia ini daripada diriku sendiri.",
  ui_story_5061_50610402_68_dialog_content = "Ayo Zarya, jangan bilang begitu! Lihat saja Luminatics-mu tadi! Saya tidak pikir seseorang yang tidak berguna bisa melakukan hal seperti itu!",
  ui_story_5061_50610402_69_dialog_content = "Dalam sekejap, kamu menyelamatkanku dari kehancuran yang pasti DAN berhasil membasmi semua Eclipsite di sekitar kita!",
  ui_story_5061_50610402_70_dialog_content = "Lumina dari serangan Anda sangat indah. Terlihat persis seperti rambut Anda...",
  ui_story_5061_50610402_71_dialog_content = "Ketika Leah pertama kali melihatmu, dia benar-benar berpikir kamu adalah Roh dari Aurora!",
  ui_story_5061_50610402_72_dialog_content = "Benar! Cara rambutmu berkilau dan bersinar... Seolah-olah Aurora memberkatinya!",
  ui_story_5061_50610402_73_dialog_content = "... Percikan api? Percikan api apa?",
  ui_story_5061_50610402_74_dialog_content = "Oh, uh... Agak canggung untuk mengakuinya, tapi aku sangat terpesona oleh rambut Nona Zarya, karena rambutku sangat pendek...",
  ui_story_5061_50610402_75_dialog_content = "Jadi, aku membantunya menyisir rambut itu saat dia tertidur. Saat itulah aku menemukan...",
  ui_story_5061_50610402_76_dialog_content = "Rambutnya memancarkan cahaya redup, seperti peninggalan ajaib dari masa lalu kuno! Tahu kan, seperti dalam cerita!",
  ui_story_5061_50610402_77_dialog_content = "R-Rambutku?! Tapi... Tapi ini bukan... Rambutku tidak selalu berwarna ini!",
  ui_story_5061_50610402_78_dialog_content = "Dia benar, rambutmu memancarkan Lumina. Ini pasti efek samping dari terjebak di dalam Luminatics-mu untuk waktu yang lama!",
  ui_story_5061_50610402_79_dialog_content = "Kamu seperti mata air Lumina yang berjalan, terus-menerus melepaskannya ke ruang di sekitarmu!",
  ui_story_5061_50610402_80_dialog_content = "Ini pasti yang Antony bicarakan sebelumnya... Mungkin kita harus menanyakannya lebih lanjut?",
  ui_story_5061_50610402_81_dialog_content = "Apakah kamu punya cara untuk menghubungi dia, Leah?",
  ui_story_5061_50610402_82_dialog_content = "Aku tahu, sebenarnya! Ikutlah denganku, dan aku akan membawamu ke desa tempat dia biasanya melakukan penelitiannya.",
  ui_story_5061_50610402_83_dialog_content = "Jika harus menebak, dia mungkin ada di sana sekarang.",
  ui_story_5061_50610501_1_dialog_content = "Lihat siapa yang ada di sini! Leah, Elf Musim Semi kita!",
  ui_story_5061_50610501_2_dialog_content = "Berpatroli di jalan pegunungan lagi hari ini?",
  ui_story_5061_50610501_3_dialog_content = "B-Benar... Tapi hari ini aku tidak di rute patroli biasa.",
  ui_story_5061_50610501_4_dialog_content = "Aku punya... beberapa urusan pribadi yang harus diurus.",
  ui_story_5061_50610501_5_dialog_content = "Apakah kedua orang ini temanmu, Leah?",
  ui_story_5061_50610501_6_dialog_content = "Nah, ini di luar dugaan. Orang luar muncul di daerah terpencil ini. Dan kamu, anak muda, sepertinya bukan berasal dari Northland.",
  ui_story_5061_50610501_7_dialog_content = "Hah? Maksudmu aku?",
  ui_story_5061_50610501_8_dialog_content = "Tentu saja. Waktu benar-benar berlalu dengan cepat, dan sekarang kita punya turis yang datang ke sini. Dulu, tempat ini sebenarnya merupakan garis depan melawan invasi Eclipsites...",
  ui_story_5061_50610501_9_dialog_content = "Jalan pegunungan tertutup salju dan terblokir. Kami, penduduk lokal, hanya bisa mengikuti erat di belakang patroli...",
  ui_story_5061_50610501_10_dialog_content = "Maaf, tim patroli yang mana yang Anda maksud?",
  ui_story_5061_50610501_11_dialog_content = "Saya tidak yakin dia membicarakan kakakmu, Nona Zarya. Jika ada yang dia maksud... Dia merujuk pada orang tua saya.",
  ui_story_5061_50610501_12_dialog_content = "Hah? Orang tuamu juga petugas patroli Northland, Leah?",
  ui_story_5061_50610501_13_dialog_content = "Ya, tapi... Mereka sudah lama meninggal.",
  ui_story_5061_50610501_14_dialog_content = "Oh, maaf. Aku tidak bermaksud membahas topik yang sensitif seperti itu.",
  ui_story_5061_50610501_15_dialog_content = "Tidak tahukah kalian bahwa Leah adalah anak yatim dari patroli?",
  ui_story_5061_50610501_16_dialog_content = "Sebenarnya, meskipun Eclipsites tidak lagi berkeliaran di sini seperti beberapa tahun lalu, pekerjaan ini tetap cukup berisiko.",
  ui_story_5061_50610501_17_dialog_content = "Ini bukan tempat seperti Istana Musim Dingin atau Danau Cermin, yang diawasi oleh Yang Mulia Ratu Queen dan Lady Nikinis...",
  ui_story_5061_50610501_18_dialog_content = "Kita hanya bisa mengandalkan anggota patroli. Tapi melihat anak-anak seperti Leah harus menangani semua ini agak sulit untuk dilihat.",
  ui_story_5061_50610501_19_dialog_content = "Ini... Ini sama sekali tidak merepotkan, sungguh! Yang Mulia Ratu mempercayakan Staff of Spring padaku, dan aku memiliki begitu banyak teman yang membantuku...",
  ui_story_5061_50610501_20_dialog_content = "Mengatasi beberapa Eclipsite sama sekali bukan masalah... Saya juga mendapatkan waktu liburan yang dibayar, yang lebih menyenangkan lagi...",
  ui_story_5061_50610501_21_dialog_content = "Huh. Bagaimanapun juga, hal-hal ini tetap membutuhkan seseorang untuk menanganinya. Dan aku tidak dalam posisi untuk memberimu lebih banyak kenyamanan.",
  ui_story_5061_50610501_22_dialog_content = "Yang bisa kami lakukan hanyalah mengucapkan terima kasih atas dedikasi Anda.",
  ui_story_5061_50610501_23_dialog_content = "Pekerjaan yang harus dikerjakan...",
  ui_story_5061_50610501_24_dialog_content = "Tahu, aku perhatikan bahwa terkadang kamu terlihat sedikit kesepian.",
  ui_story_5061_50610501_25_dialog_content = "Kamu tidak memilih pekerjaan ini hanya untuk menjadi patroller, bukan? Jika ada alasan, mungkin kamu ingin merasa lebih dekat dengan orang tuamu dengan mengikuti jejak mereka...",
  ui_story_5061_50610501_26_dialog_content = "Benar, 'kan?",
  ui_story_5061_50610501_27_dialog_content = "Ah... Kau bisa menebak isi hatiku...",
  ui_story_5061_50610501_28_dialog_content = "Itu karena kadang-kadang aku juga merasa sama persis seperti itu.",
  ui_story_5061_50610501_29_dialog_content = "Benarkah? Kamu juga merasakan hal yang sama?",
  ui_story_5061_50610501_30_dialog_content = "Sejujurnya, aku tidak benar-benar tahu apa yang kupikirkan saat menerima Staff of Spring dan menjadi seorang patroli...",
  ui_story_5061_50610501_31_dialog_content = "Mungkin itu untuk lebih dekat dengan orang tuaku... Atau mungkin aku begitu terkesan dengan Yang Mulia Ratu sehingga aku ingin berjuang di sisinya...",
  ui_story_5061_50610501_32_dialog_content = "Tapi mengambil Staff of Spring... Aku membuat pilihan itu sepenuhnya dengan keputusanku sendiri!",
  ui_story_5061_50610501_33_dialog_content = "Dan aku ingin memberi makna pada pilihan itu! Itulah sebabnya... Itulah sebabnya aku memutuskan untuk terus menjadi seorang patroller!",
  ui_story_5061_50610501_34_dialog_content = "Itu suatu kesadaran yang luar biasa, Leah.",
  ui_story_5061_50610501_35_dialog_content = "Keputusan untuk bertahan dalam jalan yang telah kamu pilih...",
  ui_story_5061_50610501_36_dialog_content = "Hei, kecil Leah! Bisakah kamu membantuku mencari tahu ke mana kedua anak dari sebelah rumah pergi?",
  ui_story_5061_50610501_37_dialog_content = "Baru saja berjanji pada orang tua mereka untuk mengawasi mereka sebentar, tapi poof, mereka menghilang dalam sekejap mata!",
  ui_story_5061_50610501_38_dialog_content = "Oh, tentu saja! Bahkan... Aku rasa aku tahu di mana harus mencari mereka!",
  ui_story_5061_50610501_39_dialog_content = "Tapi sebelum itu, bolehkah saya bertanya... Apakah kamu pernah melihat Pak Antony?",
  ui_story_5061_50610501_40_dialog_content = "Siapa yang kamu bicarakan? Apakah dia dari desa kita?",
  ui_story_5061_50610501_41_dialog_content = "Eh, tidak juga. Pak Antony adalah seorang cendekiawan yang baik hati yang baru saja pindah ke sini. Dia sering membacakan buku kepada anak-anak dan mengajari mereka tentang bintang serta cara menggunakannya untuk navigasi.",
  ui_story_5061_50610501_42_dialog_content = "Oh, ya. Kamu mengingatkanku—ada seseorang seperti itu yang tinggal dekat desa.",
  ui_story_5061_50610501_43_dialog_content = "Anak-anak bilang dia selalu mengutak-atik perangkat aneh, tapi dia cukup ramah.",
  ui_story_5061_50610501_44_dialog_content = "Jadi, dia seorang sarjana, katamu? Aku tidak bisa membayangkannya. Bukankah seharusnya para sarjana menghabiskan waktu di dalam ruangan membaca buku sepanjang hari?",
  ui_story_5061_50610501_45_dialog_content = "Tapi pria ini, dia selalu menggunakan tubuh kekar-nya, berlari di pegunungan dan kembali dengan penuh luka lebam dan terluka.",
  ui_story_5061_50610501_46_dialog_content = "Jadi, apa sebenarnya yang dia pelajari?",
  ui_story_5061_50610501_47_dialog_content = "Dia, uh, sedang meneliti asal-usul Aurorian, seperti darimana kita berasal dan kemana kita akan pergi. Anda tahu, hal-hal seperti itu.",
  ui_story_5061_50610501_48_dialog_content = "Yah, itu cukup aneh. Berlari liar di pegunungan setiap hari, apakah itu benar-benar membantunya memahami semua hal ini?",
  ui_story_5061_50610501_49_dialog_content = "Mengapa dia tidak mempelajari penyebab tanaman di sini menjadi layu? Memang tidak banyak alternatif yang bisa tumbuh di tempat dingin ini sejak awal.",
  ui_story_5061_50610501_50_dialog_content = "Maaf, aku tidak bisa memberitahu dia apa yang harus dilakukan. Lagipula, tidak semua hal memiliki jawabannya.",
  ui_story_5061_50610501_51_dialog_content = "Tapi tetap saja, Pak Antony mungkin telah meneliti sesuatu yang berkaitan dengan itu...",
  ui_story_5061_50610501_52_dialog_content = "Dia pernah bilang padaku... Bahwa \"musim semi\" memiliki dua arti yang berbeda untuk tanaman dan Aurorian.",
  ui_story_5061_50610501_53_dialog_content = "Dua musim semi yang berbeda? Apa maksudnya itu?",
  ui_story_5061_50610501_54_dialog_content = "Kurasa kita harus menanyakannya saat kita menemukannya.",
  ui_story_5061_50610501_55_dialog_content = "Bagaimanapun juga, aku harus pergi menemuinya.",
  ui_story_5061_50610501_56_dialog_content = "Sama di sini. Kedua anak itu senang bertanya banyak hal kepada Pak Antony, sama seperti saya...",
  ui_story_5061_50610501_57_dialog_content = "Mereka mungkin sedang belajar sesuatu yang baru di rumahnya jika mereka tidak ada di desa saat ini.",
  ui_story_5061_50610502_1_dialog_content = "Fyuh... Akhirnya kita di sini.",
  ui_story_5061_50610502_2_dialog_content = "Kamu bilang rumahnya ada di jalan menuju Puncak Cedar, tapi dia hampir-hampir tinggal di kaki gunung.",
  ui_story_5061_50610502_3_dialog_content = "Yah, dia memang datang ke sini untuk menyelidiki gunung ini...",
  ui_story_5061_50610502_4_dialog_content = "Ada begitu banyak buku di sini... Dan lihat, sebuah radio.",
  ui_story_5061_50610502_5_dialog_content = "Dia memiliki lebih banyak buku daripada perpustakaan... Tunggu, apa itu \"ready-o\"?",
  ui_story_5061_50610502_6_dialog_content = "Ini diucapkan \"radio,\" Nona Zarya. Sejauh yang saya tahu, kebanyakan orang luar membelinya di Umbraton...",
  ui_story_5061_50610502_7_dialog_content = "Apakah ini... catatan Bapak Antony?",
  ui_story_5061_50610502_8_dialog_content = "Coba saya lihat apakah ada petunjuk di dalamnya...",
  ui_story_5061_50610502_9_dialog_content = "Aku akan melihat-lihat juga... Astaga, dia benar-benar telah menyelidiki masalah pertumbuhan tanaman lokal yang buruk!",
  ui_story_5061_50610502_10_dialog_content = "\"Tahun demi tahun, ladang di sekitar Desa Cedar gagal menghasilkan tanaman yang sehat, dan situasi ini tampaknya semakin memburuk setiap tahunnya. Saya menduga bahwa Lumina yang tidak normal di area ini adalah penyebabnya.\"",
  ui_story_5061_50610502_11_dialog_content = "... Tulisan tangan Pak Antony lucu, menurutmu? Terlihat seperti tulisan tangan anak-anak!",
  ui_story_5061_50610502_12_dialog_content = "(Nah, itu masuk akal, mengingat pendidikan formalnya hanya saat dia masih kecil...)",
  ui_story_5061_50610502_13_dialog_content = "Dia juga memiliki beberapa skema yang digambar dengan tangan di sini. Sebuah \"tiang trekking multifungsi\"? Wah, saya tidak tahu bahwa Tuan Antony merancang dan membuat tongkat jalan yang selalu dia bawa-bawa!",
  ui_story_5061_50610502_14_dialog_content = "Sepertinya dia juga telah melalui beberapa versi. Menurut catatannya, itu terus rusak saat bertarung dengan Eclipsites...",
  ui_story_5061_50610502_15_dialog_content = "Jadi, dia fokus pada memperkuat desainnya di beberapa versi berikutnya... Itu hampir tidak terdengar \"multifungsi\" bagi saya!",
  ui_story_5061_50610502_16_dialog_content = "Saya sangat menyadari itu. Sebagai setengah manusia, saya lebih dari mampu menjaga diri sendiri. Selain itu, saya telah mengalami situasi seperti ini berkali-kali sebelumnya!",
  ui_story_5061_50610502_17_dialog_content = "Setidaknya, aku harus bisa bertahan dari serangan mereka sampai mereka kelelahan.",
  ui_story_5061_50610502_18_dialog_content = "Meskipun saat berbicara tentang dia... Daya tahan mungkin adalah fungsi yang paling berguna yang bisa dimiliki oleh apapun.",
  ui_story_5061_50610502_19_dialog_content = "PlayerName? Ini juga menyebutkan sesuatu yang disebut \"fungsi pemancar.\" Apa maksudnya?",
  ui_story_5061_50610502_20_dialog_content = "<size=45>Hati-hati! Eclipsites!</size>",
  ui_story_5061_50610502_21_dialog_content = "Eclipsites?! Di mana?!?",
  ui_story_5061_50610502_22_dialog_content = "Hahaha, kena! Kamu memang penakut!",
  ui_story_5061_50610502_23_dialog_content = "Kalian berdua di sana rupanya! Keluarga kalian sangat cemas! Bisakah kalian setidaknya memberi tahu mereka ke mana kalian pergi sebelum menghilang dari desa?",
  ui_story_5061_50610502_24_dialog_content = "Dia benar, tahu! Tidak baik juga bermain lelucon seperti ini!",
  ui_story_5061_50610502_25_dialog_content = "Anak-anak yang menangis meminta perhatian dari Eclipsites biasanya yang pertama kali dimakan!",
  ui_story_5061_50610502_26_dialog_content = "Astaga, kenapa kamu bicara seperti nenekku? Tidak ada yang menakut-nakuti anak-anak seperti itu saat ini!",
  ui_story_5061_50610502_27_dialog_content = "Lagipula, kita tahu area ini seperti punggung tangan kita. Kita sangat paham di mana tempat yang berisiko dan di mana tempat yang aman.",
  ui_story_5061_50610502_28_dialog_content = "Jika kamu tidak percaya pada kami, kami bisa menunjukkan jurus spesial kami—<color=#FFB400>Memancing Eclipsite</color>!",
  ui_story_5061_50610502_29_dialog_content = "Mau melihatnya? Kita umpan Eclipsites untuk mengejar kita, lalu bawa mereka ke dalam cahaya mercusuar. Dan bam! Eclipsites jadi hangus!",
  ui_story_5061_50610502_30_dialog_content = "Dan beberapa Eclipsite akhirnya menyadari apa yang terjadi dan langsung kabur seperti ayam—sulit menggambarkan betapa lucunya itu, hahaha!",
  ui_story_5061_50610502_31_dialog_content = "Kalian anak-anak ini gila?! Itu terlalu berbahaya!",
  ui_story_5061_50610502_32_dialog_content = "Anak-anak ini benar-benar tidak menyadari betapa beruntungnya mereka hidup dalam kedamaian...",
  ui_story_5061_50610502_33_dialog_content = "Karena sangat membosankan di sini, tahu. Tidak banyak hal menarik di perbatasan.",
  ui_story_5061_50610502_34_dialog_content = "Kecuali apa yang dikatakan oleh Pak Antony. Itu cukup menarik.",
  ui_story_5061_50610502_35_dialog_content = "Apa katanya?",
  ui_story_5061_50610502_36_dialog_content = "Tn. Antony mengatakan bahwa hal-hal dalam dongeng itu nyata!",
  ui_story_5061_50610502_37_dialog_content = "Apakah kamu ingat dongeng lama itu? Yang bercerita tentang Northland yang dulunya adalah tempat yang subur, hijau, dan penuh kehidupan?",
  ui_story_5061_50610502_38_dialog_content = "Aku punya firasat ini bukan hanya dongeng, tapi kisah nyata dari masa lalu!",
  ui_story_5061_50610502_39_dialog_content = "Yang benar?",
  ui_story_5061_50610502_40_dialog_content = "Saya menemukan sesuatu yang mungkin membuktikannya juga! Lingkaran pohon kuno yang ditemukan membeku dalam es selama berabad-abad...",
  ui_story_5061_50610502_41_dialog_content = "Perubahan iklim di suatu daerah bisa terlihat pada lingkaran pohon, lho!",
  ui_story_5061_50610502_42_dialog_content = "Bagian lingkaran pohon yang lebih renggang menunjukkan lingkungan pertumbuhan yang relatif lebih hangat pada saat itu, sedangkan bagian yang lebih rapat menunjukkan kebalikannya. Adapun pohon yang saya temukan, lingkaran paling dalamnya sangat renggang.",
  ui_story_5061_50610502_43_dialog_content = "Ini berarti bahwa pada suatu waktu, Northland adalah tempat yang hangat! Mungkin bahkan pernah mengalami musim semi yang sesungguhnya!",
  ui_story_5061_50610502_44_dialog_content = "Itu berarti dongeng itu nyata, bukan hanya sesuatu yang dibuat untuk mengecoh anak-anak! Aku akan pergi memberi tahu Nenek tentang ini!",
  ui_story_5061_50610502_45_dialog_content = "Tapi lagi, kenapa Northland begitu dingin sekarang?",
  ui_story_5061_50610502_46_dialog_content = "Yah, Northland memang berada di ketinggian yang sangat tinggi. Selain itu, juga sangat dekat dengan tanah Eternal Night, yang pastinya juga merupakan tempat yang sangat dingin.",
  ui_story_5061_50610502_47_dialog_content = "Memang, jika Northland dulunya adalah tempat yang hangat... Maka itu berarti Lingkaran Senja yang kita kenal tidak ada di sini...",
  ui_story_5061_50610502_48_dialog_content = "Seperti apakah dunia itu terlihat bertahun-tahun yang lalu...?",
  ui_story_5061_50610502_49_dialog_content = "Tuan Antony, Tuan Antony?",
  ui_story_5061_50610502_50_dialog_content = "Suaramu menjadi pelan, dan apa yang kamu katakan terlalu samar. Kami tidak bisa mengerti.",
  ui_story_5061_50610502_51_dialog_content = "Maaf, anak-anak. Dunia ini penuh dengan misteri yang belum terpecahkan sehingga bahkan aku pun kesulitan untuk memahami hal-hal tersebut.",
  ui_story_5061_50610502_52_dialog_content = "Makanya sebaiknya jangan repotkan orang lain dengan hal-hal seperti ini, ya?",
  ui_story_5061_50610502_53_dialog_content = "Saya suka sekali misteri yang belum terpecahkan! Apakah kamu tahu tentang permukaan Danau Cermin, cahaya Beacon, dan es abadi Queen?",
  ui_story_5061_50610502_54_dialog_content = "Hahaha! Meskipun agak tidak sopan untuk menanyakan rahasia Yang Mulia Ratu, dengan cukup belajar dan berkomunikasi...",
  ui_story_5061_50610502_55_dialog_content = "Mungkin suatu hari nanti kita akan tahu.",
  ui_story_5061_50610502_56_dialog_content = "Aku ingin belajar bersamamu! Aku juga penasaran apakah Roh Aurora itu nyata!",
  ui_story_5061_50610502_57_dialog_content = "Kamu sangat diterima untuk bergabung denganku suatu hari nanti, tapi diingatkan: pekerjaan ini penuh dengan bahaya dan kesulitan. Kamu perlu melatih pikiran dan tubuhmu jika ingin mengimbangi.",
  ui_story_5061_50610502_58_dialog_content = "Nah, anak-anak? Apakah kalian pikir kenakalan kalian ini termasuk latihan?",
  ui_story_5061_50610502_59_dialog_content = "Aku yakin Tn. Antony mengajari kamu lebih baik, 'kan?",
  ui_story_5061_50610502_60_dialog_content = "Maaf…",
  ui_story_5061_50610502_61_dialog_content = "... Pak Antony mengatakan kita seharusnya tidak berurusan dengan Eclipsite, dan kita harus menghargai kekuatan Beacon karena Queen telah berusaha keras untuk mempertahankannya.",
  ui_story_5061_50610502_62_dialog_content = "... Jadi, sejak saat itu kami tidak pernah bermain lagi permainan memancing Eclipsite. Kami hanya ingin pamer kepada kamu tadi...",
  ui_story_5061_50610502_63_dialog_content = "Senang kamu mengerti. Kamu membuat semua orang khawatir padamu bahkan ketika kamu hanya sedang pamer, tahu?",
  ui_story_5061_50610502_64_dialog_content = "Hmm... Maaf.",
  ui_story_5061_50610502_65_dialog_content = "Nona Zarya... Itu luar biasa! A-Aku rasa aku kurang pandai dalam melakukan percakapan yang serius dengan orang lain...",
  ui_story_5061_50610502_66_dialog_content = "Sejujurnya, tadi saya berpura-pura menjadi orang lain. Saya juga terkejut bahwa itu berhasil dengan baik...",
  ui_story_5061_50610502_67_dialog_content = "S-Sebenarnya, saya ingin belajar cara menjadi lebih penyayang seperti Leah...",
  ui_story_5061_50610502_68_dialog_content = "Tahu tidak, kamu cukup penyayang saat tertidur.",
  ui_story_5061_50610502_69_dialog_content = "Saya tidak ingat bertanya kepada Anda—",
  ui_story_5061_50610502_70_dialog_content = "Apa yang dilakukan Pak Antony akhir-akhir ini? Sudah lama sejak terakhir kali dia menceritakan kisah-kisah kepada kita...",
  ui_story_5061_50610502_71_dialog_content = "Ini agak membuatku khawatir...",
  ui_story_5061_50610502_72_dialog_content = "Dia pasti sedang menyelidiki apa yang tertulis di catatan ini: Aurorastorm, Lumina yang aneh, dan gua beku di Puncak Cedar!",
  ui_story_5061_50610502_73_dialog_content = "Tertulis di sini bahwa mungkin ada satu set besar reruntuhan yang belum teridentifikasi di suatu tempat di dalam Cedar Peak...",
  ui_story_5061_50610502_74_dialog_content = "... Mungkinkah itu sumber Lumina aneh yang aku rasakan sebelumnya?",
  ui_story_5061_50610502_75_dialog_content = "(Jadi bagaimana Zarya terhubung dengan semua ini?)",
  ui_story_5061_50610502_76_dialog_content = "Badai Aurora... dan Puncak Cedar...",
  ui_story_5061_50610502_77_dialog_content = "Apa yang sedang kulakukan sebelum aku membeku? Urgh—",
  ui_story_5061_50610502_78_dialog_content = "(Aku tidak ingin terus hidup dalam kegelapan! Aku ingin tahu... Aku ingin mengingat apa yang terjadi padaku!)",
  ui_story_5061_50610601_1_dialog_content = "Aku tidak berpikir pencarian kita akan membawa kita kembali ke tempat di mana kita menemukanmu, Zarya.",
  ui_story_5061_50610601_2_dialog_content = "Apakah kamu baik-baik saja?",
  ui_story_5061_50610601_3_dialog_content = "Aku baik-baik saja! Lagipula, aku tidak akan membiarkan kamu kembali ke gunung itu sendirian!",
  ui_story_5061_50610601_4_dialog_content = "Kamu benar-benar tidak seharusnya memaksakan diri. Aku bisa saja menunggu Leah kembali dan mengantarku ke sini.",
  ui_story_5061_50610601_5_dialog_content = "Seperti yang aku bilang! Aku baik-baik saja, jadi jangan khawatir tentang itu!",
  ui_story_5061_50610601_6_dialog_content = "Semua orang bekerja keras untuk membantuku saat ini... Apa jadinya aku jika aku membiarkan kamu menghadapi dingin dan Eclipsites sendirian...",
  ui_story_5061_50610601_7_dialog_content = "Aku hanya mencari jawaban. Dalam hal itu, aku tidak berbeda dengan Leah atau Antony...",
  ui_story_5061_50610601_8_dialog_content = "Aku ingin menghadapi masa lalu dan bertanggung jawab atas apa yang telah kulakukan, tidak peduli seberapa bodoh aku dulu. Aku menolak untuk berpura-pura seolah-olah tidak ada yang pernah terjadi.",
  ui_story_5061_50610601_9_dialog_content = "Nah, selalu baik untuk memiliki tujuan dalam pikiran.",
  ui_story_5061_50610601_10_dialog_content = "Tapi... Bukankah seharusnya kamu bersiap-siap untuk pulang sekarang? Atau mungkin mencari sesuatu untuk mengubah warna rambutmu?",
  ui_story_5061_50610601_11_dialog_content = "... Aku sudah menulis surat ke rumah memberi tahu semua orang bahwa aku aman. Namun, Kurir membutuhkan sedikit waktu lagi untuk sampai di sini.",
  ui_story_5061_50610601_12_dialog_content = "(Aku hanya berharap alamat yang aku ingat masih benar...)",
  ui_story_5061_50610601_13_dialog_content = "Itu sebabnya... Aku butuh sesuatu untuk dilakukan sementara ini.",
  ui_story_5061_50610601_14_dialog_content = "Meskipun adikku selamat, aku tidak bisa pulang sampai aku mengerti mengapa aku kehilangan kendali atas kekuatanku seperti itu.",
  ui_story_5061_50610601_15_dialog_content = "Aku hanya... Aku benar-benar perlu kembali dan mencari tahu apa yang sebenarnya terjadi padaku!",
  ui_story_5061_50610601_16_dialog_content = "Indah sekali...",
  ui_story_5061_50610601_17_dialog_content = "Hah...? A-Apa yang kau bicarakan?!",
  ui_story_5061_50610601_18_dialog_content = "Aku bicara tentang langit! Aku rasa aku tidak benar-benar menyadarinya saat kita menyelamatkanmu tadi.",
  ui_story_5061_50610601_19_dialog_content = "Saya dengar seseorang bilang bahwa tepi Lingkaran Twilight tidak terlalu jauh dari sini saat kita kembali turun gunung.",
  ui_story_5061_50610601_20_dialog_content = "O-Oh, jadi itu yang kamu maksud... Ini cukup umum bagi kami yang tumbuh di perbatasan.",
  ui_story_5061_50610601_21_dialog_content = "Sebelum hari ini, aku hanya pernah membaca tentang itu di basis data Soroz. Tidak heran Antony sangat bersemangat mengajari anak-anak tentang hal itu.",
  ui_story_5061_50610601_22_dialog_content = "Tidak banyak orang yang mengabdikan waktu atau usaha untuk memahaminya. Saya percaya bahwa Tuan Antony adalah orang yang paling bersemangat yang pernah saya temui dalam hal ini.",
  ui_story_5061_50610601_23_dialog_content = "Dengan cara yang sama, hanya sedikit orang yang berusaha memahami sumber kekuatan Beacon, atau alasan Queen melindungi Northland.",
  ui_story_5061_50610601_24_dialog_content = "Menjalani kehidupan yang sederhana pasti sangat menyenangkan. Pandangan semua orang di sini begitu murni dan tidak rumit.",
  ui_story_5061_50610601_25_dialog_content = "Mungkin ini berkaitan dengan seberapa terpisahnya Northland dari pergumulan dunia luar. Sudah sama persis begitu selama bertahun-tahun lamanya.",
  ui_story_5061_50610601_26_dialog_content = "Sebenarnya, Northland cukup berbeda dari yang masih bisa kuingat. Perbedaan yang paling jelas adalah betapa mudahnya orang luar seperti kamu bisa muncul di tempat ini.",
  ui_story_5061_50610601_27_dialog_content = "Kurasa Northland dan Caelestite memiliki kesamaan, ya? Kita berdua mengisolasi diri dari dunia untuk menjaga netralitas kita.",
  ui_story_5061_50610601_28_dialog_content = "Apakah Caelestites memiliki sangat sedikit kontak dengan dunia luar?",
  ui_story_5061_50610601_29_dialog_content = "Yep. Untuk menghindari konflik dengan dunia luar dan hidup dalam damai, orang-orangku memilih untuk menyendiri di Eraveil, tempat di mana orang luar jarang menginjakkan kaki.",
  ui_story_5061_50610601_30_dialog_content = "Bahkan sejak usia muda, kita diajarkan untuk tidak pernah pergi atau berinteraksi dengan dunia luar tanpa izin dari orang tua kita.",
  ui_story_5061_50610601_31_dialog_content = "Jadi, apa yang membuatmu meninggalkan Eraveil?",
  ui_story_5061_50610601_32_dialog_content = "Sayangnya, semua upaya kita untuk menjauh dari dunia luar tidak membuat kita aman dari para Eclipsite.",
  ui_story_5061_50610601_33_dialog_content = "Banyak tahun lalu, satu legiun Eclipsite menyerbu Eraveil, memusnahkan seluruh bangsa saya. Saya adalah satu-satunya yang selamat.",
  ui_story_5061_50610601_34_dialog_content = "Apa?! Jadi begitu saja, kaum Caelestite legendaris... Mereka semua hilang sekarang?",
  ui_story_5061_50610601_35_dialog_content = "... Aku minta maaf. Aku tidak bermaksud mengungkit kenangan menyakitkan seperti itu. Kamu pasti merasa kesepian.",
  ui_story_5061_50610601_36_dialog_content = "Haha, tidak perlu minta maaf! Seburuk apapun itu, aku sudah menerima masa lalu.",
  ui_story_5061_50610601_37_dialog_content = "Aku merasa seolah-olah aku bisa mengerti perasaanmu. Meskipun pengalaman hidupku tidak seberapa dibandingkan dengan milikmu.",
  ui_story_5061_50610601_38_dialog_content = "Saat saya kecil, saya menyebabkan banyak masalah bagi keluarga saya karena tidak bisa mengendalikan Luminatics saya.",
  ui_story_5061_50610601_39_dialog_content = "Ayahku sangat malu padaku. Dia selalu menjaga jarak, dan dia mengurungku di rumah karena takut aku akan merusak bisnisnya.",
  ui_story_5061_50610601_40_dialog_content = "Akhirnya, saya kehilangan hampir semua keterampilan sosial saya. Saya tidak punya teman atau bahkan keberanian untuk mencari teman.",
  ui_story_5061_50610601_41_dialog_content = "Saat aku mengenangnya, hidupku sebenarnya tak jauh berbeda dari saat aku terjebak di dalam es.",
  ui_story_5061_50610601_42_dialog_content = "Kamu pasti juga merasakan kesepian yang sama... Terjebak sendirian, tanpa ada teman untuk menemani.",
  ui_story_5061_50610601_43_dialog_content = "Di awal, ya. Aku menghabiskan hampir seluruh masa kecilku terjebak di ruang kecil. Jika aku ingin belajar tentang dunia luar, aku harus mengandalkan basis data Soroz.",
  ui_story_5061_50610601_44_dialog_content = "Seiring waktu, aku mulai bertanya-tanya apakah aku benar-benar ada di dunia ini.",
  ui_story_5061_50610601_45_dialog_content = "Dan sekarang, meskipun aku bisa melihat dunia dengan kedua mataku sendiri... Perasaan yang sama masih saja datang sesekali.",
  ui_story_5061_50610601_46_dialog_content = "Itulah mengapa aku memilih untuk terus maju, apapun yang terjadi. Jika aku tidak terus maju, tidak ada yang akan berubah.",
  ui_story_5061_50610601_47_dialog_content = "Kaumku dulu hidup di dunia ini dan bahkan berjuang untuk melindunginya. Aku akan melakukan hal yang sama.",
  ui_story_5061_50610601_48_dialog_content = "... Tahu tidak, berbicara denganmu rasanya seperti berbicara dengan kakakku. Kalian berdua sangat kuat namun baik hati.",
  ui_story_5061_50610601_49_dialog_content = "Tidak seperti diriku, yang selalu membuat orang lain kesal dengan pengambilan keputusan yang buruk...",
  ui_story_5061_50610601_50_dialog_content = "Jika aku lebih seperti kamu, mungkin Ayah tidak akan membelakangiku. Mungkin aku bisa menyelamatkan adik perempuanku...",
  ui_story_5061_50610601_51_dialog_content = "Alih-alih terjebak dalam es.",
  ui_story_5061_50610601_52_dialog_content = "Aku baru ingat, Caelestite seharusnya memiliki kekuatan psikis legendaris, kan? Apakah kamu juga menggunakan kekuatan itu untuk membangkitkanku?",
  ui_story_5061_50610601_53_dialog_content = "Itu benar. Bahkan, aku sedang berpikir untuk menggunakannya lagi sekarang ini.",
  ui_story_5061_50610601_54_dialog_content = "Tahu tidak, sepertinya kamu kurang mengikuti perkembangan sejarah terbaru Astra.",
  ui_story_5061_50610601_55_dialog_content = "Faktanya, rasanya seperti kamu terjebak dalam es untuk waktu yang sangat lama.",
  ui_story_5061_50610601_56_dialog_content = "H-Hey! Kamu yang mengenalkan aku pada berbagai informasi baru! Tentu saja kamu akan merasa begitu!",
  ui_story_5061_50610601_57_dialog_content = "Sst! Aku merasakan Eclipsite!",
  ui_story_5061_50610601_58_dialog_content = "Sepertinya kita sudah jauh di luar dari penghalang tak terlihat Queen Bethlehem.",
  ui_story_5061_50610602_1_dialog_content = "Aku akan menodai salju dengan darah kalian, kalian monster!",
  ui_story_5061_50610602_2_dialog_content = "Groar...",
  ui_story_5061_50610602_3_dialog_content = "Itu hampir bukan tantangan!",
  ui_story_5061_50610602_4_dialog_content = "Itu aneh... Ada yang tidak beres dengan Eclipsites ini.",
  ui_story_5061_50610602_5_dialog_content = "Apa maksudmu?",
  ui_story_5061_50610602_6_dialog_content = "Mereka mencoba untuk menjauh dari kamu. Apakah mungkin mereka bisa merasakan tingkat Lumina yang sangat tinggi pada dirimu?",
  ui_story_5061_50610602_7_dialog_content = "Hmph, itu tidak masalah bagi saya. Jika Lumina aneh ini begitu menakutkan, lebih baik saya simpan saja di dalam diri saya.",
  ui_story_5061_50610602_8_dialog_content = "Selain membuat rambutku berwarna sama seperti Aurora, sepertinya tidak ada efek lain yang mempengaruhi diriku...",
  ui_story_5061_50610602_9_dialog_content = "Aku akan berusaha sebaik mungkin mengendalikannya agar tidak membekukan kakimu lagi!",
  ui_story_5061_50610602_10_dialog_content = "Jadi kamu masih ingat aku mengeluh tentang itu, ya?",
  ui_story_5061_50610602_11_dialog_content = "Selama kamu menghindari kepala saya, kita seharusnya baik-baik saja. Saya tidak ingin menjadi beku DAN dengan rambut berwarna berbeda.",
  ui_story_5061_50610602_12_dialog_content = "Kamu nggak perlu terdengar begitu ketakutan, lho!",
  ui_story_5061_50610602_13_dialog_content = "Aku hanya sedikit gugup melihat kamu begitu familiar dengan seranganmu. Mereka hanya akan semakin kuat mulai dari sekarang...",
  ui_story_5061_50610602_14_dialog_content = "Kamu benar-benar berpikir aku bisa kehilangan kendali seburuk itu?!",
  ui_story_5061_50610602_15_dialog_content = "Bukankah itu tidak sepenuhnya mustahil? Bagaimanapun, kamu berhasil membekukan dirimu sendiri beserta setengah dari Cedar Peak!",
  ui_story_5061_50610602_16_dialog_content = "Kamu bilang kamu ingin menghadapi masa lalumu seburuk apapun itu, 'kan? Atau, apa kamu mencoba mengalihkan kesalahan kembali pada Roh Aurora?",
  ui_story_5061_50610602_17_dialog_content = "Aku…",
  ui_story_5061_50610602_18_dialog_content = "Gaah—Graaah...",
  ui_story_5061_50610602_19_dialog_content = "Baiklah, aku akui mungkin aku terlalu bersemangat saat merasakan kekuatan itu di dalam diriku...",
  ui_story_5061_50610602_20_dialog_content = "Bagus. Aku senang kita merasa sama.",
  ui_story_5061_50610602_21_dialog_content = "Berbicara tentang semangat, Pak Antony benar-benar berdedikasi pada penelitiannya, bukan? Apakah Anda benar-benar berpikir bahwa Aurora juga terhubung dengan sumber daya kuno?",
  ui_story_5061_50610602_22_dialog_content = "Saya dan saudara perempuan saya menyaksikan Aurorastorm dengan mata kami sendiri... Apakah mungkin itu berasal dari reruntuhan di dekatnya juga?",
  ui_story_5061_50610602_23_dialog_content = "Kita mungkin tidak akan tahu sampai kita bertanya langsung pada Antony sendiri...",
  ui_story_5061_50610602_24_dialog_content = "Tapi jika saya harus menebak, Lumina aneh ini mungkin alasan mengapa kamu memiliki kekuatan untuk membekukan gunung-gunung secara keseluruhan.",
  ui_story_5061_50610602_25_dialog_content = "Dan dari yang bisa saya rasakan, Lumina aneh ini berasal dari suatu tempat di bawah tanah. Mungkin ini terhubung dengan sumber Lumina yang sama yang menghasilkan Aurorastorm.",
  ui_story_5061_50610602_26_dialog_content = "Antony mengatakan bahwa sebagian masalahnya adalah kurangnya catatan terbaru tentang Aurorastorm... Yang berarti kita tidak tahu berapa lama yang lalu kejadian itu terjadi.",
  ui_story_5061_50610602_27_dialog_content = "Namun, terlepas dari kapan itu terjadi, tidak ada jejak yang tersisa...",
  ui_story_5061_50610602_28_dialog_content = "Tidak ada jejak patroli atau pertempuran yang mereka lakukan saat itu juga...",
  ui_story_5061_50610602_29_dialog_content = "Tak bisa kupercaya ingatanku menjadi sangat tidak dapat diandalkan...",
  ui_story_5061_50610602_30_dialog_content = "(Hah? Sepertinya salju di bawah kaki kita ini bersinar...)",
  ui_story_5061_50610602_31_dialog_content = "Hm? Apakah itu kelinci di sebelah pohon di sana?",
  ui_story_5061_50610602_32_dialog_content = "Kelinci adalah hewan yang sangat hati-hati. Jika mereka keluar, seharusnya area ini bebas dari bahaya yang tak terlihat...",
  ui_story_5061_50610602_33_dialog_content = "Tunggu, Zarya! Ada yang tidak beres dengan tempat ini. Biarkan aku mencoba menggunakan kekuatanku dulu.",
  ui_story_5061_50610602_34_dialog_content = "Lagi? Baiklah... Jika yang terburuk terjadi, aku akan melawan apapun yang kau temukan.",
  ui_story_5061_50610602_35_option_content = "Force Boost",
  ui_story_5061_50610602_36_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610602_37_dialog_content = "Aduh!",
  ui_story_5061_50610602_38_dialog_content = "Apa itu?! Rasanya seperti ada sesuatu yang menusuk kepala ku...",
  ui_story_5061_50610602_39_dialog_content = "J-Jangan menakutiku seperti itu! Kamu baik-baik saja...?",
  ui_story_5061_50610602_40_dialog_content = "Aku... Aku rasa mungkin aku telah membangkitkan sesuatu...",
  ui_story_5061_50610602_41_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5061_50610602_42_dialog_content = "Ada apa? Suara apa itu?!",
  ui_story_5061_50610602_43_dialog_content = "Tanahnya runtuh!",
  ui_story_5061_50610602_44_dialog_content = "Awas, Zarya!",
  ui_story_5061_50610602_45_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5061_50610602_46_dialog_content = "... Aduh!",
  ui_story_5061_50610602_47_dialog_content = "Itu tidak sepedih yang kukira.",
  ui_story_5061_50610602_48_dialog_content = "(Enggak... Rasanya seperti ada sesuatu yang menangkap kita saat kita jatuh...)",
  ui_story_5061_50610602_49_dialog_content = "...",
  ui_story_5061_50610602_50_dialog_content = "(Dengan cara itu, sepertinya cukup aman, bukan?)",
  ui_story_5061_50610602_51_dialog_content = "Hei, Zarya, kita harus...",
  ui_story_5061_50610602_52_dialog_content = "Oh tidak, dia kedinginan...",
  ui_story_5061_50610701_1_dialog_content = "Zarya, tetap di rumah hari ini, jangan kemana-mana, oke?",
  ui_story_5061_50610701_2_dialog_content = "Tapi aku belum keluar rumah selama berhari-hari...",
  ui_story_5061_50610701_3_dialog_content = "Kenapa kamu selalu ingin pergi? Kamu tidak punya teman atau keluarga yang mengawasi kamu. Atau apakah kamu berencana untuk membuat masalah dengan Luminatics-mu lagi?",
  ui_story_5061_50610701_4_dialog_content = "Ingat bagaimana kamu membekukan kereta kuda terakhir kali? Hal seperti itu tidak boleh terjadi lagi!",
  ui_story_5061_50610701_5_dialog_content = "Aku... Aku mengerti. Maaf, Ayah.",
  ui_story_5061_50610701_6_dialog_content = "(Hari kesepian lainnya di kamarku...)",
  ui_story_5061_50610701_7_dialog_content = "Oh, Zarya, lihat bunga-bunga ini—tunggu, kenapa kamu terlihat sedih?",
  ui_story_5061_50610701_8_dialog_content = "Alina... Ayah tidak mengizinkan aku keluar rumah lagi hari ini...",
  ui_story_5061_50610701_9_dialog_content = "... Ayah terlalu sibuk dengan pekerjaannya untuk memikirkan hal lain, Zarya.",
  ui_story_5061_50610701_10_dialog_content = "Dia takut bahwa dia tidak akan ada di sana untuk membantu jika terjadi sesuatu padamu. Dia tidak tahu cara lain untuk melindungimu.",
  ui_story_5061_50610701_11_dialog_content = "Aku tahu... Semua ini karena aku tidak bisa mengendalikan Luminatics-ku. Aku hanya jadi masalah...",
  ui_story_5061_50610701_12_dialog_content = "Itu tidak benar, Zarya. Lagipula, dulu aku juga punya masalah yang sama. Bahkan, aku pernah tanpa sengaja membekukan pintu depan!",
  ui_story_5061_50610701_13_dialog_content = "Aku tidak ingin ada yang tahu, makanya aku selalu menendangnya dulu sebelum membuka! Hahaha!",
  ui_story_5061_50610701_14_dialog_content = "Heh, kau tidak bisa menipuku, Alina. Kapten patroli macam apa yang tidak bisa mengendalikan kekuatannya sendiri?",
  ui_story_5061_50610701_15_dialog_content = "Tentu saja aku bisa mengendalikan mereka sekarang, tapi kamu jauh lebih kuat daripada aku pada usiamu dulu.",
  ui_story_5061_50610701_16_dialog_content = "Sebenarnya, dengan bakat seperti milikmu, kamu bahkan bisa menjadi pengawal kerajaan di istana Queen Bethlehem!",
  ui_story_5061_50610701_17_dialog_content = "Seorang pengawal kerajaan...? Tapi itu selalu menjadi mimpimu, Alina...",
  ui_story_5061_50610701_18_dialog_content = "Tapi menjadi patroller juga hebat! Aku bisa melihat berbagai tempat yang jauh, seperti gunung bersalju dan bahkan mata air panas...",
  ui_story_5061_50610701_19_dialog_content = "Dan itu tidak bisa lebih buruk daripada menjadi pelayan di Pengadilan, bukan?",
  ui_story_5061_50610701_20_dialog_content = "Kamu luar biasa, Alina... Kamu selalu penuh kekuatan dan motivasi, tidak seperti saudara perempuanmu yang tidak berguna dan tertekan.",
  ui_story_5061_50610701_21_dialog_content = "Jangan khawatir, Zarya! Kamu akan sekuat aku dalam waktu dekat... Tidak, bahkan lebih kuat!",
  ui_story_5061_50610701_22_dialog_content = "Lagipula, saya belum menyerah pada impian saya. Saya yakin suatu hari nanti saya akan menjadi pengawal kerajaan!",
  ui_story_5061_50610701_23_dialog_content = "Dan saat hari itu tiba, aku akan melindungi Northland dengan Queen!",
  ui_story_5061_50610701_24_dialog_content = "Heehee! Aku tahu kamu bisa melakukannya!",
  ui_story_5061_50610701_25_dialog_content = "Uh-oh! Sepertinya saya terlalu lama mengobrol. Hampir waktunya bertemu dengan patroli lainnya!",
  ui_story_5061_50610701_26_dialog_content = "Oh tidak! Sebaiknya kamu bergegas, Alina... Semoga berhasil dalam misi kamu!",
  ui_story_5061_50610701_27_dialog_content = "Terima kasih. Coba tetap semangat, ya? Ingat, saat Ayah marah, jangan terlalu serius menanggapi apa yang dia katakan!",
  ui_story_5061_50610701_28_dialog_content = "(... Dan kemudian dia pergi...)",
  ui_story_5061_50610701_29_dialog_content = "(Jika aku tahu apa yang terjadi selanjutnya... Aku tidak akan membiarkannya pergi.)",
  ui_story_5061_50610701_30_dialog_content = "(... Tapi masa lalu tak bisa diubah. Dalam kesedihan dan penyesalan, yang bisa kulakukan hanyalah mempertaruhkan hidupku untuk memperbaiki segalanya...)",
  ui_story_5061_50610701_31_dialog_content = "(Lokasi terakhir diketahui dari tim patroli nya... sudah dipenuhi oleh Eclipsite...)",
  ui_story_5061_50610701_32_dialog_content = "Alina! Apakah kamu di luar sana?!",
  ui_story_5061_50610701_33_dialog_content = "Roaar—",
  ui_story_5061_50610701_34_dialog_content = "Jangan menghalangiku!",
  ui_story_5061_50610701_35_dialog_content = "Alina! Tolong, jawab aku!",
  ui_story_5061_50610701_36_dialog_content = "Grrrr!",
  ui_story_5061_50610701_37_dialog_content = "Bergerak!",
  ui_story_5061_50610701_38_dialog_content = "Kakak... Apakah... Masih hidup? Aku sangat takut...",
  ui_story_5061_50610701_39_dialog_content = "... Tak perlu... takut.",
  ui_story_5061_50610701_40_dialog_content = "…!",
  ui_story_5061_50610701_41_dialog_content = "Suara itu... Apakah itu kamu, Alina?",
  ui_story_5061_50610701_42_dialog_content = "... Apakah kamu ingin menyelamatkan seseorang?",
  ui_story_5061_50610701_43_dialog_content = "Ya! A-aku ingin menyelamatkan adikku!",
  ui_story_5061_50610701_44_dialog_content = "... Aku mengakui potensimu...",
  ui_story_5061_50610701_45_dialog_content = "... Bersama kamu, mungkin misi ini... bisa diselesaikan...",
  ui_story_5061_50610701_46_dialog_content = "... Kalau begitu, kamu akan mengambil alih... kesunyianku...",
  ui_story_5061_50610701_47_dialog_content = "(Dan begitu, aku mengikuti suara itu melalui salju...)",
  ui_story_5061_50610701_48_dialog_content = "(Saya pikir itu akan membawaku menemui saudara perempuanku, tapi ternyata... Itu membawaku ke neraka yang tak pernah bisa kubayangkan.)",
  ui_story_5061_50610701_49_dialog_content = "<color=#e8d9bb>Tak terhitung jumlah petugas patroli yang terbaring diam di tanah.</color>",
  ui_story_5061_50610701_50_dialog_content = "<color=#e8d9bb>Eclipsite dengan mulut menganga dan kumpulan raungan yang keras.</color>",
  ui_story_5061_50610701_51_dialog_content = "<color=#e8d9bb>Bau menyengat yang membuat mual, masih menusuk meskipun di tengah salju yang berputar.</color>",
  ui_story_5061_50610701_52_dialog_content = "<color=#e8d9bb>Dan rawa yang seperti jurang, kental, dan menjijikkan di tanah.</color>",
  ui_story_5061_50610701_53_dialog_content = "Ini tidak nyata... Ini tidak mungkin nyata...",
  ui_story_5061_50610701_54_dialog_content = "Kalian monster kotor! Jauhi adikku!",
  ui_story_5061_50610701_55_dialog_content = "Mekarlah, Frostlight!",
  ui_story_5061_50610701_56_dialog_content = "Roaar—",
  ui_story_5061_50610701_57_dialog_content = "Jumlah mereka terlalu banyak! Saya tidak bisa mengalahkan mereka semua!",
  ui_story_5061_50610701_58_dialog_content = "Roaaaaaaar—",
  ui_story_5061_50610701_59_dialog_content = "Maaf, Alina... Aku rasa aku tidak bisa membunuh semua Eclipsite ini!",
  ui_story_5061_50610701_60_dialog_content = "Andai saja aku lebih kuat, mungkin aku bisa menyelamatkanmu sekarang...",
  ui_story_5061_50610701_61_dialog_content = "Alina... Alina! Tidaaaak!!!",
  ui_story_5061_50610701_62_dialog_content = "<size=45>Alina!!!</size>",
  ui_story_5061_50610701_63_dialog_content = "... Zarya! Bangunlah!",
  ui_story_5061_50610701_64_dialog_content = "Alina!",
  ui_story_5061_50610701_65_dialog_content = "Tenanglah, Zarya! Itu hanya mimpi buruk!",
  ui_story_5061_50610701_66_dialog_content = "...",
  ui_story_5061_50610701_67_dialog_content = "Apakah kamu ingat tanah di bawah kita amblas? Sepertinya kita jatuh ke dalam gua atau semacamnya.",
  ui_story_5061_50610701_68_dialog_content = "Sepertinya ada reruntuhan yang terperangkap dalam es di sini. Aku akan melihatnya lebih dekat...",
  ui_story_5061_50610701_69_dialog_content = "Roaar—",
  ui_story_5061_50610701_70_dialog_content = "Ah! E-Eclipsites! Oh tidak, apa yang harus kita lakukan? Saya tidak bisa mengalahkan mereka semua...",
  ui_story_5061_50610701_71_dialog_content = "Kenapa kamu panik? Apakah ini ada hubungannya dengan mimpi burukmu?",
  ui_story_5061_50610701_72_dialog_content = "Tenang, Zarya! Jangan biarkan masa lalu menghalangi masa kinimu!",
  ui_story_5061_50610701_73_dialog_content = "Roaar—",
  ui_story_5061_50610701_74_dialog_content = "Di mana Zarya yang kita kenal?! Kita sangat membutuhkannya sekarang!",
  ui_story_5061_50610701_75_dialog_content = "Energi—Menyerap! Cepat, ke sini!",
  ui_story_5061_50610701_76_dialog_content = "Suara itu...!",
  ui_story_5061_50610701_77_dialog_content = "Bangun, Zarya! Kita harus keluar dari sini!",
  ui_story_5061_50610702_1_dialog_content = "Kita seharusnya aman di sini untuk sekarang.",
  ui_story_5061_50610702_2_dialog_content = "Sudah beberapa waktu aku menjelajahi area ini. Jika dugaanku benar, seharusnya ada pintu keluar lain di dekat sini, yang mengarah ke bagian lain dari reruntuhan bawah tanah Northland.",
  ui_story_5061_50610702_3_dialog_content = "Biasanya pintu keluar yang paling berbahaya adalah saat berada di reruntuhan seperti ini.",
  ui_story_5061_50610702_4_dialog_content = "Eclipsite di sekitar mereka mulai mencair. Mereka bisa terbangun kapan saja sekarang.",
  ui_story_5061_50610702_5_dialog_content = "Es ini... Ini dibuat dari Luminatics yang sama seperti milik Zarya, bukan?",
  ui_story_5061_50610702_6_dialog_content = "Benar. Bahkan, saya punya alasan untuk percaya bahwa itu juga diproduksi oleh Nona Zarya sendiri.",
  ui_story_5061_50610702_7_dialog_content = "Kemungkinan besar itu adalah hasil ledakan dari kekuatannya yang tidak terkendali di masa lalu.",
  ui_story_5061_50610702_8_dialog_content = "Anda mengatakan... bahwa saya yang melakukan ini?",
  ui_story_5061_50610702_9_dialog_content = "Saat ini saya tidak bisa memikirkan jawaban yang lebih baik, jadi ya.",
  ui_story_5061_50610702_10_dialog_content = "Sejujurnya, Nona Zarya... Sudah lama aku ingin menanyakan sesuatu padamu, tetapi aku belum bisa menemukan kata-kata yang tepat...",
  ui_story_5061_50610702_11_dialog_content = "Apakah ini ada hubungannya dengan situasi kita saat ini?",
  ui_story_5061_50610702_12_dialog_content = "Silakan sampaikan pikiran Anda, Pak Antony. Ini adalah kali kedua Anda menyelamatkan hidup saya; menjawab pertanyaan Anda adalah hal terkecil yang bisa saya lakukan.",
  ui_story_5061_50610702_13_dialog_content = "Jika kebaikan hatimu tidak cukup untuk membuatku menerima kebenaran...",
  ui_story_5061_50610702_14_dialog_content = "Kalau begitu, aku tidak tahu apa lagi yang akan terjadi.",
  ui_story_5061_50610702_15_dialog_content = "Baiklah. Mari kita mulai dari sumber kekuatanmu.",
  ui_story_5061_50610702_16_dialog_content = "Saya pikir saya sudah memiliki pemahaman dasar tentang hal itu sekarang. Lumina aneh yang ada dalam tubuhmu berasal dari reruntuhan ini, dan sepertinya kamu diberikan kekuatan ini untuk suatu tujuan yang belum diketahui.",
  ui_story_5061_50610702_17_dialog_content = "Untuk membuktikan pendapatku... PlayerName, bisakah kamu menggunakan kekuatanmu sendiri untuk memindai es di reruntuhan ini?",
  ui_story_5061_50610702_18_dialog_content = "Eh... Oke!",
  ui_story_5061_50610702_19_option_content = "Psychic Scan",
  ui_story_5061_50610702_20_dialog_content = "Formasi es ini... Mereka pasti dipengaruhi oleh Luminatics.",
  ui_story_5061_50610702_21_dialog_content = "Hmm? Mereka bahkan memancarkan partikel Lumina!",
  ui_story_5061_50610702_22_dialog_content = "Perasaan ini... Tidak berbeda saat aku merasakan es di sekitar Zarya saat kita pertama kali bertemu.",
  ui_story_5061_50610702_23_dialog_content = "Kamu benar! Dan saat aku mendekat untuk melihat lebih dekat...",
  ui_story_5061_50610702_24_dialog_content = "Zarya, bulumu...!",
  ui_story_5061_50610702_25_dialog_content = "Hah? Kenapa rambutku tiba-tiba bersinar...?",
  ui_story_5061_50610702_26_dialog_content = "Ini adalah jenis resonansi, saya percaya. Ketika PlayerName menggunakan kekuatannya pada es, itu mulai beresonansi dengan Lumina di tubuh Anda.",
  ui_story_5061_50610702_27_dialog_content = "Tapi, bukankah itu berbahaya?",
  ui_story_5061_50610702_28_dialog_content = "Aku tidak bisa yakin... Tapi potensi bahaya ini tidak ada apa-apanya dibandingkan dengan apa yang akan kukatakan.",
  ui_story_5061_50610702_29_dialog_content = "Apa…?",
  ui_story_5061_50610702_30_dialog_content = "Ketika kita masih di permukaan, saya mendasarkan dugaan saya pada fenomena terbaru yang dikenal sebagai Badai Aurora...",
  ui_story_5061_50610702_31_dialog_content = "Dengan demikian, tidak mungkin bagi saya untuk membuat kronologi peristiwa yang dijelaskan oleh Miss Zarya. Bahkan, saya bahkan tidak bisa membuktikan bahwa itu pernah terjadi.",
  ui_story_5061_50610702_32_dialog_content = "Namun, dengan menggunakan kesaksian dari Nona Zarya sebagai dasar dugaanku...",
  ui_story_5061_50610702_33_dialog_content = "Aku segera menemukan penemuan yang mengejutkan.",
  ui_story_5061_50610702_34_dialog_content = "Yaitu, adik dari Miss Zarya, mantan kapten patroli dan anggota kehormatan dari penjaga kerajaan Northland yang dikenal sebagai <color=#FFB400>Alina</color>...",
  ui_story_5061_50610702_35_dialog_content = "Adalah tokoh terkemuka yang hidup <color=#FFB400>beberapa dekade lalu</color>!",
  ui_story_5061_50610702_36_dialog_content = "...",
  ui_story_5061_50610702_37_dialog_content = "Dengan kata lain, Badai Aurora yang Anda alami adalah peristiwa yang sama dari <color=#FFB400>seratus tahun lalu</color>.",
  ui_story_5061_50610702_38_dialog_content = "... Apa?",
  ui_story_5061_50610702_39_dialog_content = "Namun…",
  ui_story_5061_50610702_40_dialog_content = "Tapi itu berarti... <size=45>Zarya berumur <color=#FFB400>lebih dari seratus tahun</color>???</size>",
  ui_story_5061_50610801_1_dialog_content = "Dia memiliki lebih banyak buku daripada perpustakaan... Tunggu, apa itu \"ready-o\"?",
  ui_story_5061_50610801_2_dialog_content = "PlayerName? Ini juga menyebutkan sesuatu yang disebut \"fungsi pemancar.\" Apa maksudnya?",
  ui_story_5061_50610801_3_dialog_content = "Astaga, kenapa kamu bicara seperti nenekku? Tidak ada yang menakut-nakuti anak-anak seperti itu saat ini!",
  ui_story_5061_50610801_4_dialog_content = "Faktanya, rasanya seperti kamu terjebak dalam es untuk waktu yang sangat lama.",
  ui_story_5061_50610801_5_dialog_content = "(... Akhirnya aku paham mengapa sesuatu terasa begitu aneh sekarang!)",
  ui_story_5061_50610801_6_dialog_content = "(Meskipun hal-hal hampir tidak berubah di sini di Northland, waktu tetap sama tak kenal ampunnya seperti di tempat lain...",
  ui_story_5061_50610801_7_dialog_content = "(Seratus tahun berlalu sementara Zarya terperangkap dalam es...)",
  ui_story_5061_50610801_8_dialog_content = "...",
  ui_story_5061_50610801_9_dialog_content = "Tidak... Ini tak mungkin...",
  ui_story_5061_50610801_10_dialog_content = "Anda pasti bercanda, kan, Pak Antony?",
  ui_story_5061_50610801_11_dialog_content = "Maaf, tapi ini adalah kenyataannya.",
  ui_story_5061_50610801_12_dialog_content = "Kebenaran...?",
  ui_story_5061_50610801_13_dialog_content = "Jadi kebenaran... adalah bahwa dunia ini adalah satu abad setelah waktu saya sendiri?",
  ui_story_5061_50610801_14_dialog_content = "Semua orang yang kucintai... adikku... Mereka semua pergi sekarang?",
  ui_story_5061_50610801_15_dialog_content = "Dan aku... satu-satunya yang tersisa?",
  ui_story_5061_50610801_16_dialog_content = "Zarya...",
  ui_story_5061_50610801_17_dialog_content = "...",
  ui_story_5061_50610801_18_dialog_content = "... Aku tak percaya padamu!",
  ui_story_5061_50610801_19_dialog_content = "Tunggu, Zarya! Mau ke mana?",
  ui_story_5061_50610801_20_dialog_content = "Jangan repot-repot mengikutiku!",
  ui_story_5061_50610801_21_dialog_content = "Apa? Aku tidak bisa meninggalkanmu sendirian di sini!",
  ui_story_5061_50610801_22_dialog_content = "Apa kamu tahu bagaimana perasaanku saat ini? Tolong, jangan katakan sepatah kata pun lagi...",
  ui_story_5061_50610801_23_dialog_content = "Maaf, Zarya, tapi kamu harus mendengarkan aku! Aku tahu persis bagaimana perasaanmu!",
  ui_story_5061_50610801_24_dialog_content = "Aku tahu rasanya ditinggal sendirian di tempat yang dingin dan gelap!",
  ui_story_5061_50610801_25_dialog_content = "Aku tahu betapa sulitnya muncul kembali di dunia ini, hanya untuk mengetahui bahwa semua orang melupakanmu!",
  ui_story_5061_50610801_26_dialog_content = "Dan... Aku tahu betapa menyakitkannya saat akhirnya mengetahui lebih banyak tentang masa lalu, hanya untuk menemukan dirimu kembali di titik awal.",
  ui_story_5061_50610801_27_dialog_content = "...",
  ui_story_5061_50610801_28_dialog_content = "Aku... aku tahu ada yang salah sejak awal...",
  ui_story_5061_50610801_29_dialog_content = "... Tapi aku tidak ingin menerima ini! Kamu mungkin benar bahwa kekuatan baruku ini bukan milikku sendiri...",
  ui_story_5061_50610801_30_dialog_content = "Lagi pula, aku hanya seorang pengecut yang membuat segalanya semakin buruk...",
  ui_story_5061_50610801_31_dialog_content = "Andai saja aku seberani kamu...",
  ui_story_5061_50610801_32_dialog_content = "Andai saja aku sekuat... Seperti kamu atau kakakku... Hiks...",
  ui_story_5061_50610801_33_dialog_content = "Waaaaaaah—",
  ui_story_5061_50610801_34_dialog_content = "(Zarya...)",
  ui_story_5061_50610801_35_option_content = "Letakkan tangan di pundaknya",
  ui_story_5061_50610801_36_option_content = "Peluk dia dengan lembut",
  ui_story_5061_50610801_37_dialog_content = "(... Kamu tidak sendirian.)",
  ui_story_5061_50610801_38_dialog_content = "Kamu memiliki kami sekarang, Zarya... Kami di sini untukmu juga.",
  ui_story_5061_50610801_39_dialog_content = "Kapanpun kamu merasa sedih, ingatlah... Setidaknya ada satu orang lain di dunia yang tahu bagaimana rasanya ditinggalkan oleh waktu.",
  ui_story_5061_50610801_40_dialog_content = "Seseorang yang masih menghadapi berbagai masalah dalam kembali berintegrasi dengan masyarakat...",
  ui_story_5061_50610801_41_dialog_content = "Aku…",
  ui_story_5061_50610801_42_dialog_content = "Seseorang yang, meskipun memiliki kekuatan luar biasa, masih saja kakinya membeku saat mencoba membantu orang lain yang membutuhkan.",
  ui_story_5061_50610801_43_dialog_content = "<color=#e8d9bb>Gemuruh-!!!</color>",
  ui_story_5061_50610801_44_dialog_content = "...! Apa-apaan tadi itu?!",
  ui_story_5061_50610801_45_dialog_content = "Pertumbuhan es yang tidak normal menyebabkan bagian gua ini runtuh!",
  ui_story_5061_50610801_46_dialog_content = "Tidak... Ini terlalu intens untuk hanya dijelaskan sebagai \"tidak normal.\" Resonansi antara Zarya dan es mungkin menjadi penyebabnya...",
  ui_story_5061_50610801_47_dialog_content = "Meskipun bisa juga disebabkan oleh reruntuhan...",
  ui_story_5061_50610801_48_dialog_content = "Kita harus mencapai pintu keluar secepat mungkin! Kita bisa menemukannya dengan mengikuti aliran udara!",
  ui_story_5061_50610801_49_dialog_content = "Kau bisa berdiri, Zarya? Kita harus segera pergi!",
  ui_story_5061_50610801_50_dialog_content = "A... Aku baik-baik saja!",
  ui_story_5061_50610801_51_dialog_content = "Sebelah sini, PlayerName!",
  ui_story_5061_50610801_52_dialog_content = "Bahkan reruntuhan pun mulai bergoyang. Tempat ini akan runtuh kapan saja sekarang!",
  ui_story_5061_50610801_53_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5061_50610801_54_dialog_content = "Aduh, kakiku!",
  ui_story_5061_50610801_55_dialog_content = "Kau terluka!",
  ui_story_5061_50610801_56_dialog_content = "I-Ini hanya goresan, jangan khawatir! Aku masih bisa berlari!",
  ui_story_5061_50610801_57_dialog_content = "Aku bisa melihat cahaya melalui langit-langit gua di sini! Kita hampir sampai di pintu keluar, sekarang cepat!",
  ui_story_5061_50610801_58_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5061_50610801_59_dialog_content = "Awas kepalamu, PlayerName!",
  ui_story_5061_50610801_60_dialog_content = "(Sebuah balok es raksasa jatuh tepat di atas saya. Rasa sakit di kakiku memberitahu bahwa aku tidak akan bisa menghindarinya tepat waktu...)",
  ui_story_5061_50610801_61_dialog_content = "(Setidaknya... Aku harus membantu kedua orang itu untuk kabur...)",
  ui_story_5061_50610801_62_option_content = "Menyikut Zarya",
  ui_story_5061_50610801_63_dialog_content = "Awas, Zarya!",
  ui_story_5061_50610801_64_option_content = "Dorong Antony",
  ui_story_5061_50610801_65_dialog_content = "Hati-hati, Antony!",
  ui_story_5061_50610801_66_dialog_content = "... Mekarlah, Frostlight!",
  ui_story_5061_50610801_67_dialog_content = "<color=#e8d9bb>Di bawah serangan Zarya, batu besar itu hancur menjadi potongan kecil dan tersebar di sekitar.</color>",
  ui_story_5061_50610801_68_dialog_content = "Zarya... Anda menyelamatkan kami!",
  ui_story_5061_50610801_69_dialog_content = "Aku tahu... Aku tahu jika adikku ada di sini sekarang, dia tidak ingin aku terus larut dalam kesedihan...",
  ui_story_5061_50610801_70_dialog_content = "Itulah mengapa saya akan menggunakan Luminatics saya pada es ini, dan membuka jalan untukmu.",
  ui_story_5061_50610801_71_dialog_content = "Aku serahkan navigasi padamu! Jika kamu melihat Eclipsites, beri tahu di mana mereka dan aku akan melakukan yang terbaik!",
  ui_story_5061_50610801_72_dialog_content = "Siap!",
  ui_story_5061_50610801_73_dialog_content = "Mengerti. Tujuan kita adalah permukaan!",
  ui_story_5061_50610802_1_dialog_content = "Kita sudah jauh di luar jangkauan perlindungan Beacon. Menuju ke pintu keluar juga akan membawa kita ke arah yang berlawanan dari Beacon.",
  ui_story_5061_50610802_2_dialog_content = "Mulai dari sekarang, saya khawatir Eclipsite-nya hanya akan terus bertambah kuat dan banyak.",
  ui_story_5061_50610802_3_dialog_content = "…!",
  ui_story_5061_50610802_4_dialog_content = "Aku... Aku merasa ada sesuatu di dekat sini.",
  ui_story_5061_50610802_5_dialog_content = "Lebih banyak gerhana?",
  ui_story_5061_50610802_6_dialog_content = "Tidak, bukan itu.",
  ui_story_5061_50610802_7_dialog_content = "Aku merasakan keberadaan saat kita masih di permukaan. Dari yang bisa aku ketahui... Mungkin itu seorang Aurorian.",
  ui_story_5061_50610802_8_dialog_content = "Seorang Aurorian? Di tempat seperti ini?",
  ui_story_5061_50610802_9_dialog_content = "Ya, ini pasti Aurorian, tetapi ada sesuatu yang terasa berbeda.",
  ui_story_5061_50610802_10_dialog_content = "Biar kucoba menggunakan kekuatanku lagi...",
  ui_story_5061_50610802_11_option_content = "Psychic Scan",
  ui_story_5061_50610802_12_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610802_13_dialog_content = "Sudah begitu banyak tahun. Kamu melupakan aku selama bertahun-tahun ini.",
  ui_story_5061_50610802_14_dialog_content = "Sekarang, tiba-tiba muncul kembali seperti ini, untuk apa? Untuk kekuatan <color=#FFB400>Spark</color>?",
  ui_story_5061_50610802_15_dialog_content = "Sudah berlalu satu abad. Mengapa setelah diaktifkan lagi, aku merasa kekurangan energi, sementara kalian semua begitu... penuh?",
  ui_story_5061_50610802_16_dialog_content = "Aduh... K-Kepalaku...",
  ui_story_5061_50610802_17_dialog_content = "Apa... yang kamu bicarakan...?",
  ui_story_5061_50610802_18_dialog_content = "Jawablah aku, Aurorian di negeri ini, saluran yang bersedia dari Lux—penerima berkat Kilauan!",
  ui_story_5061_50610802_19_dialog_content = "Ahh!!!",
  ui_story_5061_50610802_20_dialog_content = "(Kepalaku terbelah jadi dua... Aku harus memutuskan hubungan ini!)",
  ui_story_5061_50610802_21_dialog_content = "Tunggu, Nona Zarya!",
  ui_story_5061_50610802_22_dialog_content = "Kau baik-baik saja, PlayerName? Masih bisa melihatku? Bagaimana dengan ini? Bisakah kamu merasakan aku mencubit jarimu?",
  ui_story_5061_50610802_23_dialog_content = "Hmm... Ya, aku bisa merasakanmu.",
  ui_story_5061_50610802_24_dialog_content = "Bagus, reaksimu normal dan penglihatanmu tampak baik. Sepertinya kepalamu juga tidak terluka...",
  ui_story_5061_50610802_25_dialog_content = "Aku baik-baik saja, ayo terus bergerak. Aku baru saja merasakan Aurorian yang berbahaya... Tunggu, dia...",
  ui_story_5061_50610802_26_dialog_content = "<size=45>... Dia datang!!</size>",
  ui_story_5061_50610802_27_dialog_content = "<color=#e8d9bb>Nguuung!</color>",
  ui_story_5061_50610802_28_dialog_content = "Argh! T-Tubuhku...",
  ui_story_5061_50610802_29_dialog_content = "Apa ini? Aku... Aku tidak bisa mengendalikan aliran Lumina-ku!",
  ui_story_5061_50610802_30_dialog_content = "Tubuhku terasa sangat berat...",
  ui_story_5061_50610802_31_dialog_content = "Semua kekuatanku terkuras hanya untuk berdiri...",
  ui_story_5061_50610802_32_dialog_content = "Tunggu...",
  ui_story_5061_50610802_33_dialog_content = "Lumina-mu... Bahkan Lumina dari reruntuhan ini... Semuanya terserap ke arah yang sama!",
  ui_story_5061_50610901_1_dialog_content = "<color=#e8d9bb>Di titik akhir aliran Lumina, muncul sosok berpakaian putih bersih.</color>",
  ui_story_5061_50610901_2_dialog_content = "<color=#e8d9bb>Tubuhnya melayang di tengah ruang angkasa, memancarkan aura kelembutan yang etereal, dengan cahaya surgawi di pintu keluar sebagai latar belakangnya.</color>",
  ui_story_5061_50610901_3_dialog_content = "<color=#e8d9bb>Ketika dia dengan anggun menggerakkan anggota tubuh mekanik yang rumit itu, seluruh reruntuhan seolah-olah terbangun, memancarkan kecemerlangan dan beresonansi dengannya.</color>",
  ui_story_5061_50610901_4_dialog_content = "Ini dia.",
  ui_story_5061_50610901_5_dialog_content = "Apakah kamu... Seorang Aurorian?",
  ui_story_5061_50610901_6_dialog_content = "Aku... pengelola dan penjaga reruntuhan ini, No. 33.",
  ui_story_5061_50610901_7_dialog_content = "Untuk memenuhi misi, pengambilan energi diperlukan.",
  ui_story_5061_50610901_8_dialog_content = "Tindakan Anda... telah menembus batas pertahanan.",
  ui_story_5061_50610901_9_dialog_content = "Cara bicaramu...",
  ui_story_5061_50610901_10_dialog_content = "Apa, Caelestite, apakah kamu berniat menggunakan kekuatanmu padaku, yang akan memicu serangan balik pertahananku?",
  ui_story_5061_50610901_11_dialog_content = "(Perasaan seperti pikiranku tertusuk... Apakah itu \"serangan balasan bertahan\" darinya?)",
  ui_story_5061_50610901_12_dialog_content = "Hati-hati, PlayerName. Aku merasakan ada yang salah dengan dia.",
  ui_story_5061_50610901_13_dialog_content = "Seolah-olah... ada sesuatu yang rusak pada dirinya.",
  ui_story_5061_50610901_14_dialog_content = "Ah, kamu, gadis dengan kekuatan Lumina istimewa. Kau telah menimbulkan banyak masalah untukku...",
  ui_story_5061_50610901_15_dialog_content = "Benarkah? Memangnya aku kenapa?",
  ui_story_5061_50610901_16_dialog_content = "Sebagai blok cadangan daya untuk <color=#FFB400>Spark</color>...",
  ui_story_5061_50610901_17_dialog_content = "Di sini, aliran Lumina yang teratur, lancar, dan tak terputus sangatlah penting!",
  ui_story_5061_50610901_18_dialog_content = "Kemampuan penyerapanmu yang kuat mengganggu sistem secara keseluruhan, membuat pekerjaan perbaikanku gagal berulang kali.",
  ui_story_5061_50610901_19_dialog_content = "... Kemampuan penyerapan?",
  ui_story_5061_50610901_20_dialog_content = "Jadi begitu. Mungkin itu menjelaskan mengapa warna rambut Anda berubah, Nona Zarya.",
  ui_story_5061_50610901_21_dialog_content = "Tapi jika kamu adalah penjaga tempat ini, mengapa ada Eclipsites berkeliaran bebas di mana-mana?",
  ui_story_5061_50610901_22_dialog_content = "\"Di mana-mana\"? Tidak ada konsep seperti itu. Aku hanya punya \"di sini.\"",
  ui_story_5061_50610901_23_dialog_content = "Terhubung denganku, fasilitas ini adalah milikku sepenuhnya...",
  ui_story_5061_50610901_24_dialog_content = "Misi saya... adalah untuk <color=#FFB400>menjaga keseimbangan Lumina di sini</color>. Semua hal lain tidak terkait.",
  ui_story_5061_50610901_25_dialog_content = "Apa yang kau rencanakan?",
  ui_story_5061_50610901_26_dialog_content = "Ini bukan urusanmu, orang luar. Aku harus mengeliminirnya dan mengambil kembali Lumina yang dia curi...",
  ui_story_5061_50610901_27_dialog_content = "Lumina... yang aku curi? Apa maksudmu dengan itu?",
  ui_story_5061_50610901_28_dialog_content = "Perintah: Hancurkan.",
  ui_story_5061_50610901_29_dialog_content = "Hati-hati!",
  ui_story_5061_50610901_30_dialog_content = "Berhenti! Kita masih bisa membicarakan ini!",
  ui_story_5061_50610901_31_dialog_content = "Terlambat... Sudah terlalu lama...",
  ui_story_5061_50610901_32_dialog_content = "Aku tidak akan membuang waktu untuk berharap... dan mencoba.",
  ui_story_5061_50610901_33_dialog_content = "Karena kamu tidak mau mematuhi instruksi saya, aku hanya bisa menggunakan kekerasan...",
  ui_story_5061_50610901_34_dialog_content = "Bersiaplah untuk pertempuran, semuanya!",
  ui_story_5061_50610902_1_dialog_content = "... Tutup, Tepi Frost!",
  ui_story_5061_50610902_2_dialog_content = "Serangan Lingkungan!",
  ui_story_5061_50610902_3_dialog_content = "Serangan kita tidak cukup kuat!",
  ui_story_5061_50610902_4_dialog_content = "Kita tidak bisa menyakitinya sementara Lumina kita sedang terkuras dari tubuh kita...",
  ui_story_5061_50610902_5_dialog_content = "Awas, PlayerName! Dia menyerang!",
  ui_story_5061_50610902_6_dialog_content = "Argh! ... Aku menangkapmu.",
  ui_story_5061_50610902_7_dialog_content = "Antony!",
  ui_story_5061_50610902_8_dialog_content = "Jangan khawatir tentang saya. Lumina saya mungkin tidak sekuat milik Nona Zarya, tetapi kekuatan fisik saya cukup dapat diandalkan.",
  ui_story_5061_50610902_9_dialog_content = "(... Apakah benar-benar tidak ada cara lain?)",
  ui_story_5061_50610902_10_dialog_content = "(Mereka telah melindungiku selama ini... Apakah benar-benar tidak ada yang bisa aku lakukan untuk membantu?)",
  ui_story_5061_50610902_11_dialog_content = "(Mungkin jika aku mencoba menggunakan kekuatanku lagi... Aku akan bisa menemukan titik lemahnya!)",
  ui_story_5061_50610902_12_option_content = "Force Boost",
  ui_story_5061_50610902_13_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610902_14_dialog_content = "Urgh—Kepalaku!",
  ui_story_5061_50610902_15_dialog_content = "Hentikan, PlayerName!",
  ui_story_5061_50610902_16_dialog_content = "Pikirannya terlindungi dari kekuatan psikis kamu! Kamu hanya akan menyakiti diri sendiri jika menggunakannya!",
  ui_story_5061_50610902_17_dialog_content = "A-Aku tidak bisa membiarkan kalian melakukan semua pertarungan... Itulah mengapa aku akan membantu kalian dengan cara yang bisa aku lakukan...",
  ui_story_5061_50610902_18_option_content = "Force Boost",
  ui_story_5061_50610902_19_dialog_content = "Jika ada cara untuk mengelak pertahanannya, mungkin aku bisa—",
  ui_story_5061_50610902_20_dialog_content = "Argh...! Kepalaku rasanya mau meledak!",
  ui_story_5061_50610902_21_dialog_content = "Sial... Meskipun aku menahannya, aku tidak bisa menghentikan PlayerName dari menggunakan kekuatannya.",
  ui_story_5061_50610902_22_dialog_content = "Cukup! Berhenti saja!",
  ui_story_5061_50610902_23_dialog_content = "Kamu tidak bisa terus menyakiti dirimu seperti ini, PlayerName!",
  ui_story_5061_50610902_24_dialog_content = "Itu juga berlaku untuk Anda, Pak Antony!",
  ui_story_5061_50610902_25_dialog_content = "Aku... aku berutang nyawa pada kalian berdua. Aku tidak tahan melihat kalian terluka lagi.",
  ui_story_5061_50610902_26_dialog_content = "Kamu orang baik, dan kamu masih memiliki tujuan yang ingin dicapai dalam hidup.",
  ui_story_5061_50610902_27_dialog_content = "Tunggu, Zarya, apa maksudmu dengan itu...?",
  ui_story_5061_50610902_28_dialog_content = "Aku kehilangan adikku, keluargaku, dan kehidupan yang dulu kujalani...",
  ui_story_5061_50610902_29_dialog_content = "Aku tak punya tempat untuk pergi lagi, tak ada tempat yang bisa kusebut \"rumah\"... Aku hanya cangkang kosong dari orang yang dulu pernah aku jadi.",
  ui_story_5061_50610902_30_dialog_content = "Itulah mengapa saya tidak peduli apa yang terjadi pada saya sekarang.",
  ui_story_5061_50610902_31_dialog_content = "Tapi setidaknya kalian berdua—",
  ui_story_5061_50610902_32_dialog_content = "Apa-apaan yang kamu pikir kamu lakukan, Zarya?!",
  ui_story_5061_50610902_33_dialog_content = "<color=#e8d9bb>Kegentingan-</color>",
  ui_story_5061_50610902_34_dialog_content = "Tunggu, Zarya—!",
  ui_story_5061_50610902_35_dialog_content = "Kau harus tetap hidup.",
  ui_story_5061_50610902_36_dialog_content = "Zarya!!!",
  ui_story_5061_50610902_37_dialog_content = "<size=45>Zaryaaaaaaa!!!</size>",
  ui_story_5061_50611001_1_dialog_content = "(Zarya menggunakan tiang es untuk mengantarkan kita dengan selamat keluar...)",
  ui_story_5061_50611001_2_dialog_content = "(Tak lama kemudian, pintu keluar gua benar-benar runtuh.)",
  ui_story_5061_50611001_3_dialog_content = "Kenapa... Kenapa aku tidak menyadarinya lebih cepat?!",
  ui_story_5061_50611001_4_dialog_content = "Tidak... Ini tak mungkin...",
  ui_story_5061_50611001_5_dialog_content = "Andai saja aku sekuat... Seperti kamu atau kakakku... Hiks...",
  ui_story_5061_50611001_6_dialog_content = "Waaaaaaaaaaah—",
  ui_story_5061_50611001_7_dialog_content = "Kau harus tetap hidup.",
  ui_story_5061_50611001_8_dialog_content = "Andai saja aku sekuat kamu...",
  ui_story_5061_50611001_9_dialog_content = "Saat Zarya mengetahui kebenaran, dia kehilangan semua harapan di hatinya.",
  ui_story_5061_50611001_10_dialog_content = "Setelah itu, dia hampir tidak mengucapkan sepatah kata pun. Dia hanya mengikuti kami saat kami berlari dan berjuang keluar...",
  ui_story_5061_50611001_11_dialog_content = "Maaf, seharusnya aku juga menyadari ada yang tidak beres.",
  ui_story_5061_50611001_12_dialog_content = "Dia sendirian di sana, terjebak di reruntuhan tanpa jalan keluar... Dan itu persis yang dia inginkan.",
  ui_story_5061_50611001_13_dialog_content = "... Kita perlu kembali dan menyelamatkannya, tapi bagaimana? Aku tidak bisa bertarung seperti kalian, dan kekuatan psikis ku hanya membawa malapetaka bagi diriku sendiri.",
  ui_story_5061_50611001_14_dialog_content = "Tidak hanya itu... No. 33 akan menguras Lumina-mu jika kita melawannya lagi! Apa yang harus kita lakukan?!",
  ui_story_5061_50611001_15_dialog_content = "Setidaknya untuk saat ini, kita bisa percaya bahwa kekuatan Nona Zarya tidak akan mengecewakan kita dalam waktu dekat. Dia tidak akan kalah tanpa melawan.",
  ui_story_5061_50611001_16_dialog_content = "Bahkan ketika Lumina-nya terkuras dalam pertempuran, dia masih memiliki cukup untuk menghasilkan tiang es yang membawa kita ke tempat yang aman.",
  ui_story_5061_50611001_17_dialog_content = "Juga... Seseorang yang bersedia masuk ke tempat berbahaya sendirian tidak akan begitu mudah menyerahkan hidup mereka.",
  ui_story_5061_50611001_18_dialog_content = "Jadi, apakah ada yang bisa kita lakukan untuk membantu Zarya saat ini?",
  ui_story_5061_50611001_19_dialog_content = "...Ada.",
  ui_story_5061_50611001_20_dialog_content = "Tempat ini jauh di luar perbatasan barat laut Northland, tetapi dengan bantuanmu, kita seharusnya baik-baik saja.",
  ui_story_5061_50611001_21_dialog_content = "Apa yang Anda perlu saya lakukan?",
  ui_story_5061_50611001_22_dialog_content = "Saya perlu kamu menemukan kelinci terdekat dengan kita.",
  ui_story_5061_50611001_23_dialog_content = "Kelinci?",
  ui_story_5061_50611001_24_dialog_content = "Benar. Ini hewan putih lembut sebesar ini, dengan telinga panjang dan—",
  ui_story_5061_50611001_25_dialog_content = "Aku tahu apa itu kelinci, Antony. Aku hanya tidak tahu mengapa kamu membutuhkannya sekarang.",
  ui_story_5061_50611001_26_dialog_content = "Oh, kamu punya? Kalau begitu, seharusnya tidak ada masalah untuk menemukannya!",
  ui_story_5061_50611001_27_dialog_content = "Seharusnya ada satu di tenggara... Tapi aku tidak bisa mengukur seberapa jauhnya. Kira-kira kamu bisa bantu aku?",
  ui_story_5061_50611001_28_dialog_content = "(... Sepertinya aku harus menurutinya untuk saat ini.)",
  ui_story_5061_50611001_29_option_content = "Force Boost",
  ui_story_5061_50611001_30_dialog_content = "(Ke tenggara, ya? Tunggu... Bukankah Zarya dan saya melihat kelinci di sepanjang perjalanan kesini?)",
  ui_story_5061_50611001_31_dialog_content = "(... Kita berhasil! Dan itu tepat di sana!)",
  ui_story_5061_50611001_32_dialog_content = "(Kelinci itu sepertinya juga menyadari sesuatu. Dia sedang melihat ke arah kita.)",
  ui_story_5061_50611001_33_dialog_content = "Saya menemukan satu, Antony.",
  ui_story_5061_50611001_34_dialog_content = "B-Benarkah? Itu cepat sekali! Kemampuan psikis Anda benar-benar luar biasa!",
  ui_story_5061_50611001_35_dialog_content = "Heh... Lumayan, kurasa...",
  ui_story_5061_50611001_36_dialog_content = "Pokoknya, kita harus pergi.",
  ui_story_5061_50611001_37_dialog_content = "Di sini!",
  ui_story_5061_50611001_38_dialog_content = "Bagus! Jika tidak salah, kelinci ini adalah salah satu teman dari <color=#FFB400>dia</color>.",
  ui_story_5061_50611001_39_dialog_content = "Halo, teman kecilku! Bisakah kamu membantu kami mengirim pesan kepada tuanmu, <color=#FFB400>roh gunung</color>? Tolong beritahu dia bahwa kami menemukan satu set reruntuhan yang terlupakan di sini, serta warga Northland yang telah lama hilang.",
  ui_story_5061_50611001_40_dialog_content = "<color=#e8d9bb>Kelinci itu melompat jauh, jauh ke arah Northland.</color>",
  ui_story_5061_50611001_41_dialog_content = "Sebuah \"reruntuhan yang terlupakan\"... Apakah kamu pikir itu ada hubungannya dengan \"<color=#FFB400>Spark</color>\" yang disebutkan Aurorian sebelumnya?",
  ui_story_5061_50611001_42_dialog_content = "Saya percaya begitu. Jika apa yang dia katakan itu benar, reruntuhan ini berfungsi sebagai sumber daya untuk Spark.",
  ui_story_5061_50611001_43_dialog_content = "Sebagai gantinya, Spark memberdayakan pertahanan kerajaan kita. Oleh karena itu, reruntuhan ini merupakan yang paling penting di seluruh Northland.",
  ui_story_5061_50611001_44_dialog_content = "<color=#FFB400>Beacon</color>, yang memproyeksikan penghalang yang melindungi seluruh kerajaan kita dari Eclipsite, juga merupakan bagian dari Spark.",
  ui_story_5061_50611001_45_dialog_content = "Apakah itu berarti penjaga gila yang kita temui juga bagian dari pertahanan Northland?",
  ui_story_5061_50611001_46_dialog_content = "Kuyakin hanya Queen dan roh gunung yang mengetahui hal itu.",
  ui_story_5061_50611002_1_dialog_content = "Aku tak akan pernah menyerah!",
  ui_story_5061_50611002_2_dialog_content = "(Tidak cukup Lumina untuk melukainya...)",
  ui_story_5061_50611002_3_dialog_content = "(Juga... Tidak hanya penampilannya berbeda dari Aurorian lainnya, tetapi tindakan dan pola bicaranya juga sangat aneh...)",
  ui_story_5061_50611002_4_dialog_content = "Sudah lama ingin kutanyakan sesuatu padamu...",
  ui_story_5061_50611002_5_dialog_content = "Mengapa... Mengapa suaramu terdengar persis seperti kakakku?!",
  ui_story_5061_50611002_6_dialog_content = "Suaraku...",
  ui_story_5061_50611002_7_dialog_content = "Suara Nona Alina...",
  ui_story_5061_50611002_8_dialog_content = "Kamu tahu siapa dia?! Katakan padaku, apa yang telah kamu lakukan pada adikku?!",
  ui_story_5061_50611002_9_dialog_content = "Bertemu dengannya secara langsung... Membuat perjanjian sementara...",
  ui_story_5061_50611002_10_dialog_content = "Menjadi wadah energi untuk menjalankan protokol pembersihan maksimum dan mengusir para Eclipsite...",
  ui_story_5061_50611002_11_dialog_content = "… Apa maksudmu?",
  ui_story_5061_50611002_12_dialog_content = "Alina pernah di sini... dan dia berhasil menemukanku.",
  ui_story_5061_50611002_13_dialog_content = "Di luar sana dipenuhi dengan Eclipsite, dan energinya terkuras... Aku tidak bisa pergi...",
  ui_story_5061_50611002_14_dialog_content = "Situasi yang mengerikan. Alina, dia menyerap semua energi di sini dan menjadi wadahnya. Satu-satunya solusi...",
  ui_story_5061_50611002_15_dialog_content = "Jadi untuk mengalahkan Eclipsite... Kamu mengubah saudara perempuanku menjadi wadah bagi Lumina dari reruntuhan ini?",
  ui_story_5061_50611002_16_dialog_content = "Tapi tubuh Aurorian tidak mungkin bisa menampung Lumina sebanyak itu... Bisa kah?",
  ui_story_5061_50611002_17_dialog_content = "Tidak bisa... Dia tahu dia akan mengorbankan nyawanya. Tidak ada jalan keluar.",
  ui_story_5061_50611002_18_dialog_content = "... Tidak apa-apa. Kita tidak punya pilihan lain lagi.",
  ui_story_5061_50611002_19_dialog_content = "Apa kamu benar-benar sudah memikirkannya matang-matang?",
  ui_story_5061_50611002_20_dialog_content = "Kamu telah melindungi tempat ini begitu lama... Tapi kini saatnya salah satu dari kita melindungimu.",
  ui_story_5061_50611002_21_dialog_content = "Tidak hanya itu... Tapi aku juga ingin melindungi dunia ini demi adikku.",
  ui_story_5061_50611002_22_dialog_content = "Aku kagum dengan keberanianmu. Mari kita mulai...",
  ui_story_5061_50611002_23_dialog_content = "Terima kasih... Roh Aurora. Aku serahkan sisanya padamu sekarang.",
  ui_story_5061_50611002_24_dialog_content = "Tapi, aku…",
  ui_story_5061_50611002_25_dialog_content = "Tapi, aku harap kamu bisa bertahan hidup.",
  ui_story_5061_50611002_26_dialog_content = "Teman Aurorian permukaan pertama saya.",
  ui_story_5061_50611002_27_dialog_content = "Perhitungan... memulai perhitungan...",
  ui_story_5061_50611002_28_dialog_content = "Metode untuk memastikan Anda bisa bertahan hidup...",
  ui_story_5061_50611002_29_dialog_content = "Apakah itu benar-benar... bagaimana kakakku mengorbankan dirinya?",
  ui_story_5061_50611002_30_dialog_content = "... Argh... Alina... Alina...",
  ui_story_5061_50611002_31_dialog_content = "Eror pada Echo Template!",
  ui_story_5061_50611002_32_dialog_content = "Mencoba melakukan reboot.",
  ui_story_5061_50611002_33_dialog_content = "Untuk melindungi semua orang dari Aurorastorm... untuk melindungi diriku...",
  ui_story_5061_50611101_1_dialog_content = "Eror pada Echo Template!",
  ui_story_5061_50611101_2_dialog_content = "Reboot, error; reboot, error; reboot—",
  ui_story_5061_50611101_3_dialog_content = "Peringatan: Penyusup terdeteksi di dalam fasilitas;",
  ui_story_5061_50611101_4_dialog_content = "Singkirkan, singkirkan;",
  ui_story_5061_50611101_5_dialog_content = "Apa yang terjadi? Hei! Kita belum selesai bicara!",
  ui_story_5061_50611101_6_dialog_content = "Kenapa ini tiba-tiba terjadi lagi padamu? Apakah kamu perlu aku mendinginkanmu lagi?!",
  ui_story_5061_50611101_7_dialog_content = "Menjaga tempat ini, misi satu-satunya;",
  ui_story_5061_50611101_8_dialog_content = "Semua hal lain, tidak relevan, hilangkan;",
  ui_story_5061_50611101_9_dialog_content = "Apa maksudmu?!",
  ui_story_5061_50611101_10_dialog_content = "Bukankah kamu bilang kamu melindungi semua orang dengan bantuan kakakku?",
  ui_story_5061_50611101_11_dialog_content = "Jangan bilang kamu sudah lupa?!",
  ui_story_5061_50611101_12_dialog_content = "Template di-reboot... Menemui kesalahan tidak diketahui;",
  ui_story_5061_50611101_13_dialog_content = "Ayo, semuanya.",
  ui_story_5061_50611101_14_dialog_content = "Kita harus turun se-ringan mungkin...",
  ui_story_5061_50611101_15_dialog_content = "Aku bisa melihat bagian bawah!",
  ui_story_5061_50611101_16_dialog_content = "Lihat! Itu Miss Zarya!",
  ui_story_5061_50611101_17_dialog_content = "Zarya! Kami kembali untuk menyelamatkanmu!",
  ui_story_5061_50611101_18_dialog_content = "Apa...? Kenapa? Apa kau tahu betapa sulitnya untuk mengeluarkanmu dari sini?!",
  ui_story_5061_50611101_19_dialog_content = "Sudah kubilang sebelumnya! Kamu tidak sendiri lagi!",
  ui_story_5061_50611101_20_dialog_content = "Kamu... Aku tidak bisa... Ugh, apa yang harus aku lakukan denganmu?!",
  ui_story_5061_50611101_21_dialog_content = "Kita akan baik-baik saja! Lagipula, kita sudah membuat rencana!",
  ui_story_5061_50611101_22_dialog_content = "... Rencana?",
  ui_story_5061_50611101_23_dialog_content = "Tidakkah kamu menyadari bahwa Lumina-mu tidak lagi terkuras?",
  ui_story_5061_50611101_24_dialog_content = "...Kamu benar!",
  ui_story_5061_50611101_25_dialog_content = "Sekarang, yang perlu kita lakukan adalah membatasi gerakan No. 33.",
  ui_story_5061_50611101_26_dialog_content = "Setelah itu, aku akan menunggu saat yang tepat untuk menggunakan kekuatanku padanya!",
  ui_story_5061_50611101_27_dialog_content = "Apakah kamu sudah gila, PlayerName?! Apakah kamu sudah lupa apa yang itu lakukan padamu?!",
  ui_story_5061_50611101_28_dialog_content = "No. 33 mengalami <color=#FFB400>kesalahan pada Echo Template</color> akibat kerusakan yang dialaminya, serta aktivasi yang tidak lazim.",
  ui_story_5061_50611101_29_dialog_content = "Satu-satunya yang bisa memperbaiki Echo Template-nya adalah PlayerName, dan hanya dengan menggunakan kekuatannya.",
  ui_story_5061_50611101_30_dialog_content = "Kita juga memiliki perlindungan dari <color=#FFB400>dia</color>, jadi kita seharusnya tidak akan menemui perlawanan lebih lanjut.",
  ui_story_5061_50611101_31_dialog_content = "Kamu siap, Zarya?",
  ui_story_5061_50611101_32_dialog_content = "... Ya. Aku percaya padamu!",
  ui_story_5061_50611101_33_dialog_content = "Ayo kita lakukan!",
  ui_story_5061_50611102_1_dialog_content = "Dia melambat!",
  ui_story_5061_50611102_2_dialog_content = "Aku siap.",
  ui_story_5061_50611102_3_dialog_content = "Tidak ada yang perlu ditakuti lagi.",
  ui_story_5061_50611102_4_dialog_content = "—!",
  ui_story_5061_50611102_5_dialog_content = "Lakukan, PlayerName!",
  ui_story_5061_50611102_6_option_content = "Force Boost",
  ui_story_5061_50611102_7_dialog_content = "(…!)",
  ui_story_5061_50611102_8_dialog_content = "(Aku belum pernah merasakan hal seperti ini sebelumnya...)",
  ui_story_5061_50611102_9_dialog_content = "(Kesadaranku... Terus terbang maju...)",
  ui_story_5061_50611102_10_dialog_content = "(Di dunia nyata, semua ini terjadi dalam satu momen, tetapi rasanya seolah-olah pikiran saya melayang tanpa henti melalui lautan waktu—)",
  ui_story_5061_50611201_1_dialog_content = "<color=#e8d9bb>█████ tahun lalu, Fasilitas Pasokan Daya Spark No. ███.</color>",
  ui_story_5061_50611201_2_dialog_content = "Lensa tambahan menyimpang untuk ke-4682 kali; panjang fokus perlu dikalibrasi ulang.",
  ui_story_5061_50611201_3_dialog_content = "...",
  ui_story_5061_50611201_4_dialog_content = "Kalibrasi gagal. Alasan: Kerusakan tak dapat diperbaiki pada dukungan lensa tambahan No. 44.",
  ui_story_5061_50611201_5_dialog_content = "Solusi: Gantilah dengan dukungan cadangan No. 863.",
  ui_story_5061_50611201_6_dialog_content = "... Komponen rusak diganti. Stok tersisa: 3264 unit.",
  ui_story_5061_50611201_7_dialog_content = "Pemeriksaan selesai; tidak ditemukan anomali. Pemeliharaan rutin hari ini juga selesai.",
  ui_story_5061_50611201_8_dialog_content = "<color=#e8d9bb>No. 33 ditugaskan untuk merawat berbagai perangkat di fasilitas kecil tempat dia berada, terutama Lumina Concentrator.</color>",
  ui_story_5061_50611201_9_dialog_content = "<color=#e8d9bb>Sejak kebangkitannya di dalam fasilitas, dia telah rajin melakukan pekerjaan pemeliharaan, menjalankan misi yang diberikan dengan setia.</color>",
  ui_story_5061_50611201_10_dialog_content = "Saluran Lumina mengalami penyumbatan untuk ke-78.643 kali dan memerlukan pembersihan.",
  ui_story_5061_50611201_11_dialog_content = "... Upaya pengosongan gagal. Alasan: Kerusakan tak dapat diperbaiki pada antarmuka pipa saluran 65.",
  ui_story_5061_50611201_12_dialog_content = "Solusi: Gantilah dengan pipa cadangan 264; Stok tersisa: 0 unit.",
  ui_story_5061_50611201_13_dialog_content = "Cari pipa alternatif untuk digunakan. Pipa 195, persediaan: 0 unit; Pipa 236, persediaan: 0 unit.",
  ui_story_5061_50611201_14_dialog_content = "Tidak ada pipa pengganti yang tersedia; Mencari pipa yang sedang digunakan yang cocok untuk penggantian...",
  ui_story_5061_50611201_15_dialog_content = "Menemukan pipa yang cocok di antarmuka cabang 80, dengan tingkat degradasi sebesar 39%. Mempersiapkan untuk menghapus dan menggantinya ke antarmuka 65.",
  ui_story_5061_50611201_16_dialog_content = "... Komponen rusak telah diganti.",
  ui_story_5061_50611201_17_dialog_content = "Sistem beroperasi normal, keluaran daya: 60%.",
  ui_story_5061_50611201_18_dialog_content = "...",
  ui_story_5061_50611201_19_dialog_content = "(... Untuk mengganti komponen dari Konsentrator Lumina, perangkat di sekitarnya semua dibongkar...)",
  ui_story_5061_50611201_20_dialog_content = "<color=#e8d9bb>Tapi No. 33 bukan hanya mesin; dia adalah seorang Aurorian dengan tubuh dan organ-organ yang telah dimodifikasi secara signifikan.</color>",
  ui_story_5061_50611201_21_dialog_content = "<color=#e8d9bb>Seiring berjalannya waktu, dia pun merasakan kesepian, lelah dengan kehidupan yang tak berubah di fasilitas bawah tanah itu.</color>",
  ui_story_5061_50611201_22_dialog_content = "<color=#e8d9bb>Kemudian, dia mulai mempertanyakan tujuan dari misinya sendiri.</color>",
  ui_story_5061_50611201_23_dialog_content = "... Karena penghapusan sumber daya cadangan, sistem pemanas telah tidak aktif selama 436 hari.",
  ui_story_5061_50611201_24_dialog_content = "(Mungkin cukup dingin sekarang... tapi aku sudah tidak merasakannya lagi...)",
  ui_story_5061_50611201_25_dialog_content = "(... Apakah segala yang telah kulakukan benar-benar bermakna?)",
  ui_story_5061_50611201_26_dialog_content = "(Sudah bertahun-tahun, dan tak ada seorang pun yang datang ke sini atau tahu apa yang telah saya lakukan.)",
  ui_story_5061_50611201_27_dialog_content = "(Apakah masih perlu bagi misi saya untuk terus berlanjut?)",
  ui_story_5061_50611201_28_dialog_content = "Cari modul penyimpanan data alternatif yang dapat menggantikan modul yang sedang digunakan saat ini.",
  ui_story_5061_50611201_29_dialog_content = "Tidak ada modul penyimpanan yang tidak terpakai. Cari modul pengganti yang sedang aktif digunakan...",
  ui_story_5061_50611201_30_dialog_content = "Perangkat pemeliharaan bio No. 33, kepala, Modul Penyimpanan 2, dengan tingkat degradasi sebesar 32%.",
  ui_story_5061_50611201_31_dialog_content = "(No. 33... Eh?)",
  ui_story_5061_50611201_32_dialog_content = "(Kepalaku...? Modul penyimpananku...?)",
  ui_story_5061_50611201_33_dialog_content = "...",
  ui_story_5061_50611201_34_dialog_content = "(Ya, pada titik ini, apa yang harus dikesali?)",
  ui_story_5061_50611201_35_dialog_content = "(... Aku sudah menghilangkan banyak bagian sebelumnya. Indraku tidak lagi seperti Aurorian yang hidup...)",
  ui_story_5061_50611201_36_dialog_content = "... Komponen rusak digantikan. Sistem beroperasi normal, keluaran daya: 19%.",
  ui_story_5061_50611201_37_dialog_content = "(Meskipun keluaran daya rendah, tidak ada bencana atau kecelakaan yang terjadi.)",
  ui_story_5061_50611201_38_dialog_content = "(Selain di sini, ada banyak fasilitas lain yang sedang beroperasi.)",
  ui_story_5061_50611201_39_dialog_content = "(Dengan saya atau tanpa saya, tidak ada banyak perbedaan.)",
  ui_story_5061_50611201_40_dialog_content = "(... Apakah tempat ini... masih memiliki tujuan?)",
  ui_story_5061_50611201_41_dialog_content = "<color=#e8d9bb>Ketika komponen penunjang kehidupannya perlahan dibongkar, No. 33 harus menjalani periode hibernasi yang lebih lama untuk mempertahankan fungsi bertahannya hidup.</color>",
  ui_story_5061_50611201_42_dialog_content = "<color=#e8d9bb>Dia akan bangun lagi dalam beberapa tahun; kemudian waktu berikutnya lebih dari satu dekade kemudian, dan setelah itu beberapa dekade lagi...</color>",
  ui_story_5061_50611201_43_dialog_content = "<color=#e8d9bb>100 tahun lalu, Fasilitas Pasokan Daya Spark No. ███.</color>",
  ui_story_5061_50611201_44_dialog_content = "<color=#e8d9bb><size=45>Gemuruh—</size></color>",
  ui_story_5061_50611201_45_dialog_content = "(Apa... Apa yang terjadi!)",
  ui_story_5061_50611201_46_dialog_content = "(Ugh... Bangun dari hibernasi, kepala ini sakit... Diagnostik darurat!)",
  ui_story_5061_50611201_47_dialog_content = "(Tangki energi mengalami kerusakan tak dapat diperbaiki; Lumina berkeaslian tinggi menyebar, menyebabkan <color=#FFB400>ledakan energi</color> di permukaan;)",
  ui_story_5061_50611201_48_dialog_content = "(Mengapa, dari semua komponen, yang menjadi reservoir energi? Itu adalah bagian terkuat dari konsentrator... bagaimana bisa rusak...)",
  ui_story_5061_50611201_49_dialog_content = "(... Oh, benar... karena sudah sangat lama... cukup lama hingga segalanya menjadi rusak...)",
  ui_story_5061_50611201_50_dialog_content = "(... Sudah berapa tahun yang berlalu? Saya tidak bisa mengingat karena beberapa modul penyimpanan hilang...)",
  ui_story_5061_50611201_51_dialog_content = "Roaar—",
  ui_story_5061_50611201_52_dialog_content = "(Eclipsites ada di sini?... Benar, sistem pertahanan sudah gagal sejak lama..)",
  ui_story_5061_50611201_53_dialog_content = "(... Semua di sini... rusak...)",
  ui_story_5061_50611201_54_dialog_content = "(Ahhhh... akhirnya... apakah semuanya akhirnya berakhir...)",
  ui_story_5061_50611201_55_dialog_content = "(Pada saat-saat terakhir, tidak ada yang menyadari semua yang telah kulakukan selama bertahun-tahun...)",
  ui_story_5061_50611201_56_dialog_content = "(Sudah lama aku menerima takdirku untuk runtuh bersama tempat ini...)",
  ui_story_5061_50611201_57_dialog_content = "(Namun, tak seorang pun tahu tentang keberadaanku, tak ada yang sadar akan kontribusi yang telah aku berikan...)",
  ui_story_5061_50611201_58_dialog_content = "(Siapa pun boleh... setidaknya, datanglah... dan pandanglah aku sebentar...)",
  ui_story_5061_50611201_59_dialog_content = "(Siapapun...)",
  ui_story_5061_50611201_60_dialog_content = "Dimana saya...?",
  ui_story_5061_50611201_61_dialog_content = "!",
  ui_story_5061_50611201_62_dialog_content = "Hmm? Apakah kamu... seorang Aurorian?",
  ui_story_5061_50611201_63_dialog_content = "—",
  ui_story_5061_50611201_64_dialog_content = "(Echo Template-ku tidak lagi bisa mendukungku untuk membuat suara apa pun. Jadi, aku hanya bisa mengulurkan tanganku secara insting...)",
  ui_story_5061_50611201_65_dialog_content = "(Aku mengulurkan tangan kepada orang yang menyelamatkanku dari kesepian yang tak berujung—Miss Alina.)",
  ui_story_5061_50611201_66_dialog_content = "(Aku menggunakan \"bagian\" dari Miss Alina untuk memperbaiki Echo Template-ku, sehingga aku bisa membuat suara..)",
  ui_story_5061_50611201_67_dialog_content = "(Aku menceritakan misiku padanya, dan dia memberitahuku tentang apa yang terjadi di permukaan.)",
  ui_story_5061_50611201_68_dialog_content = "(Ledakan energi yang dipicu oleh kerusakan Konsentrator Lumina disebut <color=#FFB400>Badai Aurora</color> oleh mereka yang berada di luar.)",
  ui_story_5061_50611201_69_dialog_content = "Lumina abnormal yang dihasilkan oleh Aurorastorm menarik sejumlah besar Eclipsite.",
  ui_story_5061_50611201_70_dialog_content = "(Kerusakan fasilitas... menyebabkan kelainan pada Lumina eksternal, Eclipsite yang berkeliaran, dan membahayakan kelangsungan hidup Aurorian di permukaan.)",
  ui_story_5061_50611201_71_dialog_content = "(Selama ini, aku selalu berpikir bahwa misi ku adalah menjaga perangkat tetap berfungsi.)",
  ui_story_5061_50611201_72_dialog_content = "(Namun, sebenarnya, apakah tujuan sebenarnya saya adalah untuk menjaga lingkungan demi kelangsungan hidup Aurorian?)",
  ui_story_5061_50611201_73_dialog_content = "Maaf, tapi aku tidak bisa meninggalkan tempat ini. Memutuskan sambungan bisa menyebabkan ketidakstabilan fasilitas yang lebih parah.",
  ui_story_5061_50611201_74_dialog_content = "Meskipun kondisi fasilitas itu tidak lagi menjadi kekhawatiran saya, saya tidak ingin dunia di luar sana mengalami bencana yang lebih mengerikan dari yang sudah ada.",
  ui_story_5061_50611201_75_dialog_content = "Apakah benar-benar tidak ada cara lain?",
  ui_story_5061_50611201_76_dialog_content = "... Dengan peralatan di sini, saya dapat mengkonsentrasikan Lumina yang meletus di sini kepadamu, sehingga kamu dapat melepaskan energi ini pada Eclipsites di luar...",
  ui_story_5061_50611201_77_dialog_content = "Dengan cara ini, kamu bisa mengusir kawanan Eclipsite sambil menghentikan perluasan Aurorastorm.",
  ui_story_5061_50611201_78_dialog_content = "Namun, tubuh Aurorian tidak dapat menahan energi sebesar itu, yang berarti kamu kemungkinan akan hancur dalam beberapa menit.",
  ui_story_5061_50611201_79_dialog_content = "(Cahaya tunggal yang telah lama kucari selama periode ini, apakah benar aku akan melepaskannya dengan tanganku sendiri...)",
  ui_story_5061_50611201_80_dialog_content = "... Tidak apa-apa. Kita tidak punya pilihan lain lagi.",
  ui_story_5061_50611201_81_dialog_content = "(Tolong, aku memohon padamu, jangan korbankan dirimu. Kamu adalah cahaya yang telah aku tunggu dengan sangat sabar untuk kulihat.)",
  ui_story_5061_50611201_82_dialog_content = "Apa kamu benar-benar sudah memikirkannya matang-matang?",
  ui_story_5061_50611201_83_dialog_content = "Kamu telah melindungi tempat ini begitu lama... Tapi kini saatnya salah satu dari kita melindungimu.",
  ui_story_5061_50611201_84_dialog_content = "Tidak hanya itu... Tapi aku juga ingin melindungi dunia ini demi adikku.",
  ui_story_5061_50611201_85_dialog_content = "(Tidak... Aku tidak ingin kehilanganmu!)",
  ui_story_5061_50611201_86_dialog_content = "Aku kagum dengan keberanianmu. Mari kita mulai...",
  ui_story_5061_50611201_87_dialog_content = "Ini pasti... ingatan No. 33!",
  ui_story_5061_50611201_88_dialog_content = "Apakah berhasil, PlayerName?",
  ui_story_5061_50611201_89_dialog_content = "Benar! Ingatannya sedang dalam proses pemulihan!",
  ui_story_5061_50611201_90_dialog_content = "Ya, aku ingat sekarang. Misi ku bukan hanya menjaga tempat ini...",
  ui_story_5061_50611201_91_dialog_content = "Dan juga, untuk menjaga dunia luar? Alina—",
  ui_story_5061_50611201_92_dialog_content = "Eror pada Echo Template!",
  ui_story_5061_50611201_93_dialog_content = "Jadi, mengapa dia belum sembuh?",
  ui_story_5061_50611201_94_dialog_content = "Aku harus menggunakan kekuatanku sekali lagi! Kali ini, aku yakin bisa mencapai inti kesadaran dirinya!",
  ui_story_5061_50611201_95_dialog_content = "Memaksa modul memori untuk dimatikan...",
  ui_story_5061_50611201_96_dialog_content = "Jangan! Tidak! Aku tidak ingin melupakan dia!",
  ui_story_5061_50611201_97_dialog_content = "<size=45>Selamatkan aku! SELAMATKAN AKU! AHHHHH!</size>",
  ui_story_5061_50611202_1_dialog_content = "Ughhhhh...",
  ui_story_5061_50611202_2_dialog_content = "Dia berhenti!",
  ui_story_5061_50611202_3_dialog_content = "Anda harus membantunya, PlayerName!",
  ui_story_5061_50611202_4_option_content = "Force Boost",
  ui_story_5061_50611202_5_dialog_content = "<color=#e8d9bb>Di lautan kesadaran yang tak terduga, sosok yang rapuh meringkuk.</color>",
  ui_story_5061_50611202_6_dialog_content = "Misiku... misiku, misiku adalah...",
  ui_story_5061_50611202_7_dialog_content = "Konsentrator Lumina telah dibuang! Sekarang yang perlu saya lakukan adalah mematikannya dan menutup tempat ini.",
  ui_story_5061_50611202_8_dialog_content = "Aku tahu selama ini berat bagimu, tapi misi kamu akhirnya selesai.",
  ui_story_5061_50611202_9_dialog_content = "…!",
  ui_story_5061_50611202_10_dialog_content = "Maaf butuh waktu lama bagi kami untuk menemukanmu. Kamu pasti merasa sangat kesepian selama ini.",
  ui_story_5061_50611202_11_dialog_content = "Kenapa! Kenapa kamu baru datang kepadaku sekarang?",
  ui_story_5061_50611202_12_dialog_content = "Lumina telah tersumbat begitu lama, peninggalan telah rusak begitu lama, dan saya telah salah begitu lama...",
  ui_story_5061_50611202_13_dialog_content = "Aku sudah memutuskan untuk menyerah...",
  ui_story_5061_50611202_14_dialog_content = "Tapi kamu tidak pernah menyerah, kan? Dan untuk itu, kami akan selalu bersyukur.",
  ui_story_5061_50611202_15_dialog_content = "...",
  ui_story_5061_50611202_16_dialog_content = "Northland telah damai selama bertahun-tahun, semua berkat kamu yang tak pernah menyerah.",
  ui_story_5061_50611202_17_dialog_content = "Tempat-tempat yang tidak dilindungi oleh reruntuhan ini dengan cepat dikuasai oleh Eclipsites.",
  ui_story_5061_50611202_18_dialog_content = "Namun, orang-orang Northland telah hidup bahagia dan damai untuk waktu yang sangat lama... Dan itu semua berkat Anda.",
  ui_story_5061_50611202_19_dialog_content = "... Benarkah, karena aku?",
  ui_story_5061_50611202_20_dialog_content = "Misi ku... memiliki makna?",
  ui_story_5061_50611202_21_dialog_content = "Tentu saja! Misi Anda mempengaruhi seluruh Northland, dan setiap Aurorian yang tinggal di sini!",
  ui_story_5061_50611202_22_dialog_content = "Mencapai akhir bukanlah tujuan dari misi Anda... Makna sebenarnya terletak pada setiap momen damai yang Anda bawa untuk rakyat kerajaan ini.",
  ui_story_5061_50611202_23_dialog_content = "Jadi terima kasih... Terima kasih atas segalanya yang telah Anda lakukan untuk kami.",
  ui_story_5061_50611202_24_dialog_content = "… Terima kasih.",
  ui_story_5061_50611202_25_dialog_content = "... Aku ingat, dulu... ada seseorang yang menemukanku dalam keadaan seperti ini juga...",
  ui_story_5061_50611202_26_dialog_content = "... Berterima kasih atas usahaku dan bahkan menjadi temanku.",
  ui_story_5061_50611202_27_dialog_content = "Dan ada banyak orang lain yang juga ingin berteman denganmu! Kau tidak perlu menanggung beban ini sendirian lagi!",
  ui_story_5061_50611202_28_dialog_content = "Semua orang di sini bersedia untuk bertarung di sampingmu!",
  ui_story_5061_50611202_29_dialog_content = "... Tapi aku... Setelah keluar dari pertempuran, semua alat koneksi berhenti berfungsi.",
  ui_story_5061_50611202_30_dialog_content = "...Saat ini, aku hanyalah seonggok logam tak berguna.",
  ui_story_5061_50611202_31_dialog_content = "... Aku tak berguna untukmu.",
  ui_story_5061_50611202_32_dialog_content = "Itu sama sekali tidak benar. Hatimu, kata-katamu, pikiranmu... Semua hal itu memberi kita kekuatan dan membantu menjadikan dunia tempat yang lebih baik.",
  ui_story_5061_50611202_33_dialog_content = "Jantung? Pikiran? Maksudmu... kamu ingin unit penyimpananku? Internal atau eksternal?",
  ui_story_5061_50611202_34_dialog_content = "Eh... sepertinya tidak ada bedanya, ya! Ngomong-ngomong, bisakah kamu ceritakan sesuatu? Apakah Northland dulu tempat yang hangat?",
  ui_story_5061_50611202_35_dialog_content = "Ini hangat.",
  ui_story_5061_50611202_36_dialog_content = "Kenapa, sih?",
  ui_story_5061_50611202_37_dialog_content = "Karena posisi lingkaran temaram yang berbeda, di masa lalu dunia ini, tidak ada hal seperti siang abadi dan malam abadi.",
  ui_story_5061_50611202_38_dialog_content = "Aku mengerti, jadi Antony benar sejak awal! Terima kasih banyak, No. 33! Kamu baru saja memberikan jawaban yang sangat penting tentang masa lalu dunia ini!",
  ui_story_5061_50611202_39_dialog_content = "Namun, aku tidak tahu mengapa seperti ini, dan aku tidak bisa memberikan jawaban yang sebenarnya untukmu.",
  ui_story_5061_50611202_40_dialog_content = "Tidak apa-apa juga! Menemukan kebenaran adalah tujuan dari perjalanan kita. Ini adalah sesuatu yang setiap Aurorian yang hidup tahu, dalam satu cara atau lainnya.",
  ui_story_5061_50611202_41_dialog_content = "Aku tahu.",
  ui_story_5061_50611202_42_dialog_content = "Ngomong-ngomong... Mau ikut dengan kami?",
  ui_story_5061_50611202_43_dialog_content = "Aku?",
  ui_story_5061_50611202_44_dialog_content = "Tentu saja! Bagaimanapun, kamu juga bagian dari dunia kita. Bukankah kamu ingin mengalaminya sendiri?",
  ui_story_5061_50611202_45_dialog_content = "Ayo! Memang langkah pertama selalu yang paling sulit, tapi kamu akan baik-baik saja!",
  ui_story_5061_50611202_46_dialog_content = "... Tapi... perangkat koneksi ku... Aku sudah kehilangan kemampuan untuk menerima sinyal eksternal. Aku...",
  ui_story_5061_50611202_47_dialog_content = "Ambil langkah satu per satu, dan aku janji kamu tidak akan jatuh.",
  ui_story_5061_50611202_48_dialog_content = "Mereka tidak menyebutku Navigator tanpa alasan, tahu! Aku akan jadi matamu, jadi tetap semangat!",
  ui_story_5061_50611202_49_dialog_content = "Ini...",
  ui_story_5061_50611202_50_dialog_content = "Sebuah pemancar yang dibuat secara improvisasi dan berantakan... dikonfigurasi khusus untuk mencocokkan saluranku...",
  ui_story_5061_50611202_51_dialog_content = "Siap? Tiga, dua, satu...",
  ui_story_5061_50611202_52_dialog_content = "Selamat datang di dunia luar!",
  ui_story_5061_50611202_53_dialog_content = "Maaf, tadi kita tidak sempat saling memperkenalkan diri dengan baik.",
  ui_story_5061_50611202_54_dialog_content = "Ini adalah Master Novio, roh gunung dari Northland. Perisainya melindungi Lumina kita agar tidak terserap tadi.",
  ui_story_5061_50611202_55_dialog_content = "Itulah bagaimana PlayerName berhasil menggunakan kekuatannya pada No. 33 tanpa mendapatkan serangan balik.",
  ui_story_5061_50611202_56_dialog_content = "Senang bertemu denganmu, Nona Zarya.",
  ui_story_5061_50611202_57_dialog_content = "Demi Northland, serta masa depan semua Aurorian, saya harus meminta agar kita merahasiakan insiden ini.",
  ui_story_5061_50611202_58_dialog_content = "Meskipun kejadian hari ini sangat penting, kita tidak bisa membiarkan kekuatan lain mengetahui apa yang terjadi di sini. Mengingat keadaan saat ini, kita tidak punya pilihan selain mengizinkan penyelidikan dari pihak luar hingga tingkat tertentu ke tempat ini.",
  ui_story_5061_50611202_59_dialog_content = "Namun demikian, saya dengan rendah hati memohon agar Anda menjaga hubungan antara reruntuhan ini dan Spark sebagai rahasia yang terjaga dengan baik.",
  ui_story_5061_50611202_60_dialog_content = "Meskipun wabah Eclipsite selalu menjadi masalah bagi Yang Mulia Ratu... Namun itu bukanlah kekhawatiran utama yang paling mendesak.",
  ui_story_5061_50611202_61_dialog_content = "Aurorian, dan dorongan destruktif mereka untuk kekuatan yang lebih besar... Inilah yang paling mengkhawatirkan Queen Bethlehem.",
  ui_story_5061_50611202_62_dialog_content = "... Mengerti. Dunia ini masih belum siap untuk penemuan seperti ini.",
  ui_story_5061_50611202_63_dialog_content = "... Baiklah, Master Novio.",
  ui_story_5061_50611202_64_dialog_content = "Terima kasih semua atas kerja samanya. Mohon maaf, aku harus pergi sekarang...",
  ui_story_5061_50611202_65_dialog_content = "<size=45>Tunggu!</size>",
  ui_story_5061_50611202_66_dialog_content = "Hmm? Apakah... ada masalah, Zarya?",
  ui_story_5061_50611202_67_dialog_content = "A-Aku minta maaf, aku tidak bermaksud berteriak seperti itu...",
  ui_story_5061_50611202_68_dialog_content = "A... Aku hanya ingin tahu... Apa yang terjadi pada adikku pada akhirnya...",
  ui_story_5061_50611202_69_dialog_content = "Namanya Alina. Seratus tahun yang lalu, dia...",
  ui_story_5061_50611202_70_dialog_content = "... adalah kapten dari Spring Patrollers, yang hadir saat insiden Aurorastorm. Benarkah itu?",
  ui_story_5061_50611202_71_dialog_content = "K-Kamu masih ingat?!",
  ui_story_5061_50611202_72_dialog_content = "Pengetahuan Anda tampaknya sedikit usang, Nona Zarya.",
  ui_story_5061_50611202_73_dialog_content = "Hah?",
  ui_story_5061_50611202_74_dialog_content = "Sekarang, izinkan aku... Tidak, tolong izinkan aku menyampaikan \"akhir\" dari Nona Alina kepada kamu.",
  ui_story_5061_50611202_75_dialog_content = "... Kamu!",
  ui_story_5061_50611202_76_dialog_content = "Tidak perlu khawatir. PlayerName sudah membantu saya untuk menghidupkan kembali Template Echo saya dan memulihkan ingatan saya. Namun, dia belum bangun dari kelelahan yang sangat besar.",
  ui_story_5061_50611202_77_dialog_content = "Aku yang sekarang tidak akan lagi terlibat dalam tindakan yang tak terkendali.",
  ui_story_5061_50611202_78_dialog_content = "... O-Oke, tolong beritahu aku apa yang terjadi pada kakakku.",
  ui_story_5061_50611202_79_dialog_content = "Pada hari itu, tepat ketika Miss Alina memutuskan untuk mengorbankan dirinya...",
  ui_story_5061_50611202_80_dialog_content = "Alina! Apakah kamu di luar sana?!",
  ui_story_5061_50611202_81_dialog_content = "Itu terdengar seperti Zarya! Tapi bagaimana dia bisa menemukanku di sini?!",
  ui_story_5061_50611202_82_dialog_content = "Ada penyimpangan dalam kalibrasi otomatis konsentrator!",
  ui_story_5061_50611202_83_dialog_content = "Ini tertarik oleh kapal cadangan yang lebih kuat!",
  ui_story_5061_50611202_84_dialog_content = "(Jika saya memilih individu dengan bakat dan tingkat kelangsungan hidup yang lebih tinggi untuk menyelesaikan protokol... mereka semua akan dapat bertahan hidup!)",
  ui_story_5061_50611202_85_dialog_content = "Perhitungan selesai! Eksekusi rencana optimal!",
  ui_story_5061_50611202_86_dialog_content = "Apa yang harus saya lakukan sekarang?!",
  ui_story_5061_50611202_87_dialog_content = "Lari! Semakin jauh, semakin baik! Tempat ini akan segera hancur total!",
  ui_story_5061_50611202_88_dialog_content = "Tapi, apa yang akan terjadi pada kamu dan Zarya?!",
  ui_story_5061_50611202_89_dialog_content = "—Nona Zarya ingin kamu bertahan hidup, dan begitu juga aku.",
  ui_story_5061_50611202_90_dialog_content = "Kemudian, dalam satu gerakan cepat, kamu melepaskan seluruh kekuatanmu, membinasakan semua Eclipsite yang ada di sana.",
  ui_story_5061_50611202_91_dialog_content = "Sebagai efek samping dari energi tersebut, itu menyegel kamu dan seluruh reruntuhan dalam es.",
  ui_story_5061_50611202_92_dialog_content = "Alasan kamu bisa mengakses kenangan saya melalui Lumina reruntuhan tadi adalah karena reruntuhan tersebut sudah mengakui kamu sebagai bagian darinya.",
  ui_story_5061_50611202_93_dialog_content = "Apakah itu berarti adikku... berhasil kabur?",
  ui_story_5061_50611202_94_dialog_content = "Ya. Tak lama kemudian, Lady Alina kembali dengan selamat ke Northland bersama rekan-rekannya yang terluka.",
  ui_story_5061_50611202_95_dialog_content = "Saat itulah dia melaporkan keberadaan No. 33... Atau lebih tepatnya, Roh Aurora.",
  ui_story_5061_50611202_96_dialog_content = "... Jadi dia selamat, ternyata! Adikku berhasil keluar hidup-hidup!",
  ui_story_5061_50611202_97_dialog_content = "Tunggu... Jika aku menjadi wadah baru, dan Alina selamat karena itu...",
  ui_story_5061_50611202_98_dialog_content = "Apakah itu berarti... aku melindunginya?",
  ui_story_5061_50611202_99_dialog_content = "Sepertinya begitu. Lady Alina sangat hancur karena kehilangan adik perempuannya dan, sama seperti kamu, datang ke tempat ini untuk mencari kamu.",
  ui_story_5061_50611202_100_dialog_content = "Sayangnya, lapisan es yang menutupi gunung saat itu lebih tebal, dan keadaan tidak aktif No. 33 membuatnya tidak bisa mengirim atau menerima sinyal. Akibatnya, upaya pencarian kami sia-sia.",
  ui_story_5061_50611202_101_dialog_content = "Alina... Aku sangat menyesal. Tidak bisa kubayangkan betapa banyak penderitaan yang harus kamu alami...",
  ui_story_5061_50611202_102_dialog_content = "Namun demikian, Lady Alina segera menemukan kekuatan untuk melanjutkan tugas-tugasnya.",
  ui_story_5061_50611202_103_dialog_content = "!",
  ui_story_5061_50611202_104_dialog_content = "Ketika saya mengatakan bahwa pengetahuan Anda sedikit ketinggalan zaman, bukan hanya karena kakak perempuan Anda berhasil bertahan hidup...",
  ui_story_5061_50611202_105_dialog_content = "Namun karena Lady Alina kemudian menjadi <color=#FFB400>Penjaga Pengadilan Northland</color>. Dia melayani dengan setia dan terpuji selama bertahun-tahun, dan meninggal dengan tenang di usia yang mulia delapan puluh tiga tahun.",
  ui_story_5061_50611202_106_dialog_content = "Seorang penjaga istana kerajaan... Itulah mimpinya!",
  ui_story_5061_50611202_107_dialog_content = "*menangis* Aku... Aku sangat bahagia... Adikku berhasil mewujudkan mimpinya!",
  ui_story_5061_50611202_108_dialog_content = "Pada hari promosinya, Lady Alina mengucapkan kata-kata ini:",
  ui_story_5061_50611202_109_dialog_content = "Fiuh! Sepertinya akhirnya aku sekuat yang Zarya selalu pikirkan!",
  ui_story_5061_50611202_110_dialog_content = "Jangan khawatir, Alina... Aku akan pastikan hidup dengan baik untuk kita berdua!",
  ui_story_5061_50611202_111_dialog_content = "Aku melindungimu... Apakah itu membuatku kuat juga? Hiks...",
  ui_story_5061_50611202_112_dialog_content = "Aku... Aku janji akan hidup dengan baik untuk kita berdua juga...",
  ui_story_5061_50611202_113_dialog_content = "Terima kasih, Alina... Kakakku yang manis, yang sangat manis...",
  ui_story_5061_50611202_114_dialog_content = "<size=45>...Waaaaaaah!!!</size>",
  ui_story_5061_50611202_115_dialog_content = "(Aduh... Kepalaku pusing...)",
  ui_story_5061_50611202_116_dialog_content = "(Apakah ada seseorang... yang menangis?)",
  ui_story_5061_50611202_117_dialog_content = "Zarya... tadi kamu menangis ya?",
  ui_story_5061_50611202_118_dialog_content = "…!",
  ui_story_5061_50611202_119_dialog_content = "T-Tentu saja tidak!",
  ui_story_5061_50611202_120_dialog_content = "Tapi matamu merah dan bengkak...",
  ui_story_5061_50611202_121_dialog_content = "Ini hanya salju! Salju masuk ke mataku!",
  ui_story_5061_50611202_122_dialog_content = "Pfffff—",
  ui_story_5061_50611202_123_dialog_content = "Dan apa yang sedang Anda tertawakan, Pak Antony?!",
  ui_story_5061_50611202_124_dialog_content = "Oh, tidak apa-apa! Pokoknya, Master Novio, terima kasih banyak untuk—",
  ui_story_5061_50611202_125_dialog_content = "Hah? Ke mana dia pergi?",
  ui_story_5061_50611202_126_dialog_content = "Barusan dia memang di sini...",
  ui_story_5061_50611301_1_dialog_content = "<color=#e8d9bb>Suatu saat nanti...</color>",
  ui_story_5061_50611301_2_dialog_content = "Baiklah, itu seharusnya menjadi batch terakhir dari bagian-bagian.",
  ui_story_5061_50611301_3_dialog_content = "Mengumpulkan semua komponen ini sungguh tantangan. Kami menyisir setiap jengkal gunung hanya untuk mendapatkan ini!",
  ui_story_5061_50611301_4_dialog_content = "Beruntung, Master Novio telah memantau dengan cermat reruntuhan yang tersebar di seluruh kerajaan kita. Jika tidak, kita tidak akan pernah mengumpulkan begitu banyak bagian yang dapat digunakan.",
  ui_story_5061_50611301_5_dialog_content = "Meskipun usaha terbaik kami, kami masih belum dapat memperbaiki fasilitas ini. Aku minta maaf.",
  ui_story_5061_50611301_6_dialog_content = "Mengapa kamu minta maaf, No. 33? Kita tidak mencoba memperbaiki reruntuhan, ingat? Kita hanya ingin mematikan konsentrator Lumina.",
  ui_story_5061_50611301_7_dialog_content = "Setelah menilai kerusakan konsentrator secara mendalam, Winter Palace menilai bahwa alat ini terlalu berbahaya untuk digunakan lebih lanjut. Keputusan yang paling masuk akal saat ini adalah mematikannya.",
  ui_story_5061_50611301_8_dialog_content = "Master Novio sedang mengatur pasokan daya dari reruntuhan terdekat untuk menggantikan kurangnya cakupan penghalang. Lumina dari reruntuhan ini juga akan dialihkan.",
  ui_story_5061_50611301_9_dialog_content = "Setidaknya, itu kurang lebih bagaimana aku memahami rencananya. Namun, sisanya, di luar pemahamanku...",
  ui_story_5061_50611301_10_dialog_content = "Dalam hal ini, anomali Lumina seharusnya dapat diatasi cukup cepat.",
  ui_story_5061_50611301_11_dialog_content = "Setelah konsentrator dinonaktifkan, Pengadilan dapat mengatur perbaikan pada tanggal yang ditentukan nanti.",
  ui_story_5061_50611301_12_dialog_content = "Jadi menurutmu kita bisa menonaktifkan konsentrator dengan menggunakan suku cadang ini?",
  ui_story_5061_50611301_13_dialog_content = "Ya, penonaktifan langsung mungkin memicu runtuhnya atau ledakan. Kita perlu menunggu hingga modul inti diperbaiki sebelum mematikannya.",
  ui_story_5061_50611301_14_dialog_content = "Selama penutupan, Lumina yang terakumulasi dalam jangka panjang di dalam konsentrator akan dibersihkan.",
  ui_story_5061_50611301_15_dialog_content = "Ini mungkin menyebabkan gempa kecil dan fenomena aurora. Harap bersiap menghadapi dampak yang mungkin terjadi.",
  ui_story_5061_50611301_16_dialog_content = "Baiklah, saya akan memulai proses penutupan sekarang.",
  ui_story_5061_50611301_17_dialog_content = "Setelah dinonaktifkan, kamu tidak perlu terhubung dengannya lagi, kan?",
  ui_story_5061_50611301_18_dialog_content = "Ya. Aku tidak memerlukan koneksi, setidaknya sampai pekerjaan perbaikan dimulai.",
  ui_story_5061_50611301_19_dialog_content = "Lalu... Kamu mau melihat-lihat Colossus-ku?",
  ui_story_5061_50611301_20_dialog_content = "Kamu bilang ingin melihat bagaimana Aurorian lain hidup di dunia ini, bukan?",
  ui_story_5061_50611301_21_dialog_content = "?",
  ui_story_5061_50611301_22_dialog_content = "Aku…",
  ui_story_5061_50611301_23_dialog_content = "Aku mengalami emosi yang jarang tercatat sebelumnya. Apakah ini... keraguan?",
  ui_story_5061_50611301_24_dialog_content = "Mungkin kegembiraan ini hanya mempengaruhi pikiranmu? Hmm, aku penasaran bagaimana kamu akan menggambarkannya...",
  ui_story_5061_50611301_25_dialog_content = "Mengerti! Perangkat penyimpanan Anda sedang mengalami kelebihan beban sementara!",
  ui_story_5061_50611301_26_dialog_content = "Lihat, ini mulai!",
  ui_story_5061_50611301_27_dialog_content = "<color=#e8d9bb>Gemuruh — Gemuruh — Gemuruh—</color>",
  ui_story_5061_50611301_28_dialog_content = "<color=#e8d9bb>Lumina yang lama tersumbat akhirnya terlepas sekarang, kembali ke siklus energi Astra.</color>",
  ui_story_5061_50611301_29_dialog_content = "<color=#e8d9bb>Sekali lagi, aurora yang mempesona muncul di langit di perbatasan.</color>",
  ui_story_5061_50611301_30_dialog_content = "Kamu benar-benar harus melihatnya untuk percaya...",
  ui_story_5061_50611301_31_dialog_content = "Aurora ini seperti di dalam dongeng. Saya tidak menyangka sesuatu seperti ini bisa diciptakan oleh mesin.",
  ui_story_5061_50611301_32_dialog_content = "Di benua Astra, terdapat banyak fasilitas energi seperti ini.",
  ui_story_5061_50611301_33_dialog_content = "Kekuatan mereka terhubung langsung ke inti Bumi, melambangkan kehebatan luar biasa peradaban kuno dalam mengubah bentuk dunia.",
  ui_story_5061_50611301_34_dialog_content = "Tapi aurora seperti ini hanya bisa dilihat di sini, bukan?",
  ui_story_5061_50611301_35_dialog_content = "Benar sekali. Ini hanya terlihat di sini karena posisi kita dekat dengan lingkaran temaram, di mana cahaya dan kegelapan bertemu.",
  ui_story_5061_50611301_36_dialog_content = "Langit di daerah ini sangat jernih, dan tumbukan partikel Lumina sangat mencolok di sini!",
  ui_story_5061_50611301_37_dialog_content = "Aku telah bermimpi tentang momen ini lebih banyak dari yang bisa kuhitung... Tapi, tak ada yang bisa menyamai melihatnya dengan mata kepala sendiri.",
