  ui_story_5061_50611301_40_dialog_content = "(Mengetahui bahwa orang seperti dia bisa mengungkap rahasia dunia dan mewujudkan mimpinya juga membuat saya bahagia.)",
  ui_story_5061_50611301_41_dialog_content = "Akhirnya saya mengerti mengapa kamu terus mencari jawaban atas pertanyaan-pertanyaan paling sulit dalam hidup, Antony.",
